insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Songs', 'B4.1.1.1', 'Exhibit knowledge of traditional and occupational songs by recognising their types and their related songs', 'B4.1.1.1.1', 'Sing and discuss songs connected to traditional occupations and their importance', 'Let learners sing a familiar traditional song.; Show learners a video of a traditional song being performed.; Discuss the lyrics of the song with learners.; Let learners sing songs connected to the traditional occupation in their locality (Pick one occupation at a time).; After watching a video on a performed traditional occupation, allow the learners to discuss some importance of traditional occupation songs. Work songs: – reduce fatigue, boredom provides enjoyment allows systematic work, inspires fellow workers to work harder etc.', 10),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Poems', 'B4.1.2.1', 'Demonstrate knowledge and understanding of selected poems by discussing them', 'B4.1.2.1.1', 'Explore the poems of about five lines correctly and discuss the moral lessons in the poem', 'Let learners sing a popular traditional song.; Explore a poem to learners.; Let them listen and take note of keywords words in the poem.; Ask learners to mention the words they heard.; Write the words on the board.; Lead learners to say the words aloud.; Let learners say the words and use them to form their own sentences.; Let learners explore the poem correctly.; Put learners in groups.; Let them discuss the moral lessons in the poems in groups and tell the class.', 20),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Listening and Story Telling', 'B4.1.4.1', 'Demonstrate knowledge on the structure and features of folktales', 'B4.1.4.1.1', 'Retell a folktale of about three scenes and recognise its beginning and end and discuss the features of the folktale', 'Let learners sing a popular song.; Play a video of someone telling a folktale.; Encourage learners to take note of whatever they see and hear.; Teach learners what a folktale is.; Call learners individually to retell what they saw and heard in the video.; Put learners into groups and ask them to compose a folktale on any topic of their choice.; Let learners present their folktales to the class.; After watching the video on someone telling a folktale, lead learners to discuss what they saw and heard.; Tell learners a folktale.; Discuss the beginning and end of the folktale with learners. E.g. Beginning or opening, middle or body and end or conclusion.; Let learners discuss the features of the folktale. E.g. People, animals, spirits, tress, river, mountains, etc. It has a moral lesson and is very interesting. It is usually a comedy or tragedy.', 30),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Dramatisation and Role Play', 'B4.1.5.1', 'Demonstrate an understanding of changing a story to drama', 'B4.1.5.1.1', 'Narrate a story line of a story of about five characters and recognise and discuss the characters and setting of the story', 'Let learners sing any traditional work song they know.; Invite a guest teacher to tell a short story made up of five characters.; Discuss what a story line is with learners.; Lead learners through discussion to find out the story line of the story they have heard.; Let learners listen to the story again from the guest teacher.; Discuss what a setting and a character is with learners.; Allow learners to recognise the characters and setting of the story.', 40),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Dramatisation and Role Play', 'B4.1.5.1', 'Demonstrate an understanding of changing a story to drama', 'B4.1.5.1.2', 'Perform the drama of about five characters', 'Discuss the story that the guest teacher told the class again with learners.; Assign roles to them and direct learners to perform the drama.; Discuss the performance with learners.; The strengths and weaknesses must be emphasized in order to improve on subsequent performances.', 50),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B4.1.6.1', 'Talk about personal experiences and that of others', 'B4.1.6.1.1', 'Narrate any interesting experiences in life', 'Ask learners to mention some traditional plays they know.; Ask learners to sing the songs associated with the plays.; Give an account of any interesting experience you have had in life as a teacher.; Discuss the narrated experience with learners.; Allow learners to also narrate any interesting experience they have had in life.', 60),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Conversation', 'B4.1.6.1', 'Talk about personal experiences and that of others', 'B4.1.6.1.2', 'Respond/react to other peoples’ stories or narratives', 'Let learners narrate their experiences in life (it could be an experience at the hospital, school, home or the playing field).; Discuss the experience narrated with learners.; Let learners express their views on the experiences narrated.; Lead learners to recognise the various positive reactions to other people’s experiences.', 70),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B4.1.7.1', 'Show an understanding of what an environment is and the effect of environmental degradation', 'B4.1.7.1.1', 'Talk about the environment and recognise and discuss things that destroy the environment', 'Take a stroll with learners.; Tell them to take note of the things they see as you take the stroll.; Let learners mention the names of things in their environment.; In class, discuss what an environment is with learners.; In class, discuss the trip with learners and lead them to recognise some of the actions of man that destroy the environment.; Let learners recognise other things that destroy the environment. E.g. Bushfires, erosion, de-forestation, pollutions in various forms, etc.', 80),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Talking about Oneself, Family, People and Places', 'B4.1.7.1', 'Show an understanding of what an environment is and the effect of environmental degradation', 'B4.1.7.1.2', 'Describe how to prevent things that destroy the environment', 'Discuss the actions that destroy the environment again with learners.; Group learners and ask them to brainstorm in their various groups on what they think must be done to prevent the destruction of the environment.; Let each group present whatever they have written down to the class.; Let learners discuss the points raised by their friends and select the major ideas that they bring out (the teacher can add more ways of preventing the destruction of the environment in case the points raised by learners are not very strong).; Show learners a video on how to prevent things that destroy the environment.; Discuss the video with them.', 90),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B4.1.9.1', 'Demonstrate knowledge on understanding and use of polar question', 'B4.1.9.1.1', 'Recognise polar question markers', 'Revise the lesson on giving and responding to commands with learners.; Call one learner and use the questions and answers strategy to get information from him or her as the rest of the learners listen.; Discuss what polar question markers are with learners.', 100),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Asking and Answering Questions', 'B4.1.9.1', 'Demonstrate knowledge on understanding and use of polar question', 'B4.1.9.1.2', 'Recognise anduse polar question markers correctly', 'Let learners come out in pairs.; Let one ask a polar question for the other to answer and vice versa (supervise the questioning so that you provide an assistance where necessary).; Use question and answer strategy, to get information from one of the learners on the use of polar question markers.; Let them recognise polar questions in your question.; Lead learners to recognise how to use polar question markers correctly.', 110),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Giving and Following Commands/Instructions', 'B4.1.10.1', 'Exhibit knowledge of understanding and use of landmarks in giving directions', 'B4.1.10.1.1', 'Recognise landmarks in your area and use them to give directions', 'Revise the lesson on the environment with learners.; Show learners map of Ghana with the landmarks very visible.; Discuss the map with learners telling them what a landmark is and how to recognise the landmarks.; Let the learners mention some of the popular landmarks they see on the map.; Let learners recognise landmarks in their locality.; Let learners mention some of the popular landmarks they know ones again.; Use the landmarks to give directions.; Let learners use landmarks on the school compound to give directions to specific places in the school.; Let learners use landmarks to give directions to key places in the locality.', 120),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B4.1.11.1', 'Demonstrate knowledge and understanding of the names and sequence of days of the week and months of the year', 'B4.1.11.1.1', 'Say the time by hour, half hour and minutes', 'Revise the lesson on telling the time with learners.; Show a wall clock to learners.; Discuss the various parts of the clock with learners (i.e. numbers, hour hand, minute hand and the second hand).; Use the clock to teach the time by hour. Place the hour and minutes hand properly on the numbers and call learners to tell the time by hour.; Use the clock to tell the time by hour, half an hour and in minutes.; Let learners tell time by hour, half hour, and minutes.; Lead learners to know when to write the time with “am” and “pm”(am for morning and pm for afternoon till eleven in the night). E.g. The time is 6 o’clock. The time is 7:30am. The time is 7:12pm.', 130),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B4.1.11.1', 'Demonstrate knowledge and understanding of the names and sequence of days of the week and months of the year', 'B4.1.11.1.2', 'Say the names of the week in sequence', 'Let learners say the letters of the alphabet.; Create a game with the names of the days in a week.; Play the game with learners in the classroom.; Let learners mention the names of the week in sequence and use the names of the days of the week to form simple sentences.; Write the names of the days of the week on the board and lead learners to mention them.; Let learners say the names of the days of the week in turns. E.g. Sunday, Monday, Tuesday etc.', 140),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Oral Language (Listening and Speaking)', 'Presentation', 'B4.1.11.1', 'Demonstrate knowledge and understanding of the names and sequence of days of the week and months of the year', 'B4.1.11.1.3', 'Say the names of the months in sequence', 'Create a game with the names of the months of the year.; Play the game with learners in the classroom.; Help learners to mention the names of the months in sequence.; Let learners form sentences with the names of the months of the year. E.g. January, February, March, April, etc.', 150),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter Sound Knowledge', 'B4.2.4.1', 'Demonstrate knowledge in listening and pronouncing words with identical sounds from a list of words', 'B4.2.4.1.1', 'Read and recognise sounds at word initial', 'Let learners say the letters of the alphabet as a group and then individually.; Write a number of words on the board.; Lead learners to say the words as a group and then individually.; Let learners use the knowledge they have on letters and sounds and sorting to group words with the same initial sounds together in a group.; Let learners show their works to another group.; Through this, help learners read and recognise sounds at word initial.', 160),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter Sound Knowledge', 'B4.2.4.1', 'Demonstrate knowledge in listening and pronouncing words with identical sounds from a list of words', 'B4.2.4.1.2', 'Read and recognise diagraphs in sentences', 'Let learners say the letters of the alphabet as a group and individually.; Write a number of sentences on the board.; Lead learners to read the sentences as a group and individually.; Lead learners to recognise the diagraphs in the sentences.; Let learners read the diagraphs in the words that are in sentences.', 170),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter Sound Knowledge', 'B4.2.4.1', 'Demonstrate knowledge in listening and pronouncing words with identical sounds from a list of words', 'B4.2.4.1.3', 'Blend two-syllables to form words', 'Revise the lesson on syllables with learners.; Write two syllable words on the board and help learners to read them.; Put learners into groups and ask them to form as many words as they can by blending two-syllable words and mention their words to the class.', 180),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Phonics: Letter Sound Knowledge', 'B4.2.4.1', 'Demonstrate knowledge in listening and pronouncing words with identical sounds from a list of words', 'B4.2.4.1.4', 'Recognise and say consonant clusters in words found in paragraphs', 'Let learners say the letters of the alphabet.; Write words with consonant clusters in them (where applicable) and lead learners to say the words as a group and individually.; Use words formed with consonant clusters to form sentences on the board and lead learners to read the sentences.; Let learners read the sentences and as they read, lead them to recognise the consonant clusters in the sentences and write them down.', 190),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and content vocabulary)', 'B4.2.5.1', 'Show an understanding of, recognise and read about things in their environment', 'B4.2.5.1.1', '1 Read aloud with correct pronunciation and tone', 'Sing a song with learners. Read aloud a passage.; Read the passage again while learners read after you.; Let learners read aloud the passage with correct pronunciation and tone (correct them where necessary).', 200),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and content vocabulary)', 'B4.2.5.1', 'Show an understanding of, recognise and read about things in their environment', 'B4.2.5.1.2', 'Find meanings of unfamiliar words from context', 'Read aloud the passage again.; Mention some words and write them on the board.; Lead learners to find the meaning of the words in context.; Let learners find the meanings of more unfamiliar words in context.', 210),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Vocabulary (Sight and content vocabulary)', 'B4.2.5.1', 'Show an understanding of, recognise and read about things in their environment', 'B4.2.5.1.3', 'Find meanings of figurative expressions', 'Read a passage aloud.; Write the figurative expressions in the passage on the board.; Lead learners through discussions to find the meanings of the figurative expressions.; Let learners find the meanings of more figurative expressions.', 220),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B4.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B4.2.6.1.1', '1 Explain the meanings of unfamiliar words', 'Let learners sing a song they know.; Read aloud a passage.; Read the passage again while learners repeat after you.; Let learners read the passage as a group and individually.; Let learners read a paragraph of the passage in turns.; Ask learners to mention unfamiliar words they see in the passage and write the words on the board.; Discuss the words with learners to get the meanings of the words.; Group learners and let them find the meanings of given unfamiliar words.; Let learners explain the meanings of unfamiliar words.', 230),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B4.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B4.2.6.1.2', 'Explain the meanings of figurative expressions', 'Read aloud a passage.; Write the figurative expressions in the passage on the board.; Lead learners to read the figurative expressions as a group and individually.; Lead learners through discussion to find the meanings of the figurative expressions.; Let learners find the meanings of more figurative expressions', 240),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Comprehension', 'B4.2.6.1', 'Exhibit knowledge of answering questions based on texts presented', 'B4.2.6.1.3', 'Answer factual questions', 'Let learners read the passage again in turns.; Call a learner to ask a question based on the passage read for the other learners to answer.; Ask questions for learners to answer.', 250),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B4.2.7.1', 'Demonstrate in knowledge on reading for comprehension', 'B4.2.7.1.1', 'Explain the meanings of unfamiliar words in a text', 'Lead learners to sing a song.; Read a passage silently.; Ask learners to recognise and write unfamiliar words down.; Let learners mention the words to the class.; Write the words on the board and group learners to find the meanings of the given words.; In groups, let the learners explain the meanings of the unfamiliar words in a text among themselves.', 260),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B4.2.7.1', 'Demonstrate in knowledge on reading for comprehension', 'B4.2.7.1.2', 'Explain the meanings of figurative expressions in a text', 'Read a passage.; Write the figurative expressions in the passage on the board.; Lead learners to read the figurative expressions as a group and individually.; Lead learners through discussion to find the meanings of the figurative expressions.; Let learners find the meanings of more figurative expressions.', 270),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Silent Reading', 'B4.2.7.1', 'Demonstrate in knowledge on reading for comprehension', 'B4.2.7.1.3', 'Answer questions on a passage', 'Let learners read the passage again in turns.; Call a learner to ask questions based on the passage read for the other learners to answer.; Ask questions for learners to answer.', 280),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Fluency', 'B4.2.8.1', 'Exhibit knowledge by reading with minimal mistakes', 'B4.2.8.1.1', 'Read short passages observing punctuations', 'Give learners short passages to read in silently.; Call learners to read the passage in turns (correct learners where necessary).; As they read, let them observe the punctuations in the passage.', 290),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Fluency', 'B4.2.8.1', 'Exhibit knowledge by reading with minimal mistakes', 'B4.2.8.1.2', 'Read about 125 to 150 words per minute', 'Give learners a passage to read (the passage should be about 125 to 150 words to be read in a minute.); Group learners and let them play a reading game at 120 words or more per minute.', 300),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Summarising', 'B4.2.9.1', 'Show an understanding of how main ideas are extracted from a text', 'B4.2.9.1.1', 'Select topic sentences in paragraphs', 'Let learners sing a traditional occupational song.; Let learners read a number of paragraphs from a book.; Lead learners to discuss what a topic sentence is.; Lead learners to recognise some topic sentences in the passage they have read.; Let learners continue with the reading of the passage and write down the topic sentences in each paragraph read.; Let learners compare their topic sentences in their groups.; Let learners compare their final group works to those of other groups.; Discuss their findings with them.', 310),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Summarising', 'B4.2.9.1', 'Show an understanding of how main ideas are extracted from a text', 'B4.2.9.1.2', 'Give titles to passages', 'Read a passage to learners.; Discuss the passage with learners and let them come out with suggested titles.; Discuss their suggested titles with them and select one.; Give learners a different printed passage for them to read.; Lead learners to give a title to the passage they have read.', 320),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B4.3.1.1', 'Exhibit knowledge of the use of full stops, commas and question marks appropriately in sentences, and write simple sentences boldly and clearly', 'B4.3.1.1.1', 'Recognise that, full stop is used at the end of a complete sentence', 'Write a number of sentences on a cardboard.; Use full stops at the end of each sentence you write.; Lead learners to read the sentences as a group and in turns.; Ask learners to tell you the punctuation marks they see at the end of the sentences and tell them that the full stop is used at the end of a complete sentence.; Write more sentences on the board without full stops and ask learners to use the full stop to punctuate them.', 330),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B4.3.1.1', 'Exhibit knowledge of the use of full stops, commas and question marks appropriately in sentences, and write simple sentences boldly and clearly', 'B4.3.1.1.2', 'Recognise that a comma is used to separate a list of items. It serves as a pause in sentences and speech', 'Draw some items on a cardboard.; Call learners to mention the names of the items you have drawn on the board and write the names down horizontally.; Use commas to separate the items you have written.; Let learners recognise that a comma is used to separate a list of items in a row.; Let learners also know that the comma serves as a pause in sentences and speech as well (show an example of this in a passage).; Group learners and assign a leader.; Let learners mention names of items for the group leader to write.; Let the group now separate the items with a comma and show their work to other groups and discuss their findings.', 340),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B4.3.1.1', 'Exhibit knowledge of the use of full stops, commas and question marks appropriately in sentences, and write simple sentences boldly and clearly', 'B4.3.1.1.3', 'Recognise that a question mark is used at the end of a question', 'Revise command and response with learners.; Write some questions on a cardboard.; Lead learners to read the questions.; Use question marks at the end of each of the questions.; Let students read the questions again in turns.; Let learners recognise that question marks are used at the end of a question.; Write more questions on the board and call learners to come out to punctuate them using the question mark.', 350),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing', 'Penmanship/Handwriting', 'B4.3.1.1', 'Exhibit knowledge of the use of full stops, commas and question marks appropriately in sentences, and write simple sentences boldly and clearly', 'B4.3.1.1.4', '(cont’d)', null, 360),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Narrative Writing', 'B4.4.1.1', 'Show an understanding in using punctuation marks appropriately in writing sentences', 'B4.4.1.1.1', 'Demonstrate the use of commas in narrative writing', 'Revise the lesson on the use of commas with learners.; Discuss what a narrative writing is with learners.; Group learners and ask them to write a short narrative essay.; Let the groups read their essays to the class for the class to discuss (the discussion should focus on the parts in the essay that learners think a comma had been used or left out).', 370),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Narrative Writing', 'B4.4.1.1', 'Show an understanding in using punctuation marks appropriately in writing sentences', 'B4.4.1.1.2', 'Write sentences using full stops effectively', 'Revise the lesson on the use of the full stop as a punctuation mark with learners.; Write a number of sentences on a cardboard.; Use full stops at the end of each sentence you write.; Show the cardboard to learners and call them to read the sentences individually.; Help learners recognise that full stop is used at the end of a complete sentence.; Allow learners to construct some sentences in groups.; Let them show their sentences to the class and discuss the sentences with the class.', 380),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Narrative Writing', 'B4.4.1.1', 'Show an understanding in using punctuation marks appropriately in writing sentences', 'B4.4.1.1.3', 'Recognise and use the question marks appropriately in narrative writing', 'Give learners a narrative writing that has question marks used in the right way.; Let learners read aloud the narrative writing in turns.; As they read, let them take note of how question marks have been used.; Let them recognise and use the question marks appropriately in narrative writing.; Allow learners to read with the correct intonation.; Write a four sentence paragraph on the board and allow learners to put the question marks at the appropriate positions.', 390),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Creative/ Free Writing', 'B4.4.2.1', 'Show an understanding of composing short simple stories', 'B4.4.2.1.1', 'Write a one paragraph story describing a past event', 'Let learners sing a popular traditional song they know.; Share the class Readers/Reading books to learners and ask them to open to a page where there is a passage made up more than one paragraph.; Lead learners to read the passage.; Use the passage to assist learners to recognise a paragraph.; Narrate a past event to learners and put them into groups to write a one paragraph story describing the event narrated to them.', 400),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Creative/ Free Writing', 'B4.4.2.1', 'Show an understanding of composing short simple stories', 'B4.4.2.1.2', 'Create a scene and write a short story on it', 'Show learners a short video.; In groups, let learners discuss the scenes they saw in the movie.; Let learners write a short story on the scene they saw and read their story to the class.; Discuss their stories with them.', 410),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Descriptive Writing', 'B4.4.3.1', 'Exhibit the knowledge in writing of descriptive essays using controlled composition', 'B4.4.3.1.1', 'Describe pictures using controlled composition', 'Let learners mention some landmarks in the locality.; Show learners a number of pictures.; Let learners pick any of the displayed pictures and describe it.; Using the controlled composition approach, let learners describe a picture.', 420),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Descriptive Writing', 'B4.4.3.1', 'Exhibit the knowledge in writing of descriptive essays using controlled composition', 'B4.4.3.1.2', 'Give a description of a building or a structure using controlled composition', 'Let learners mention some traditional occupations they know.; Write the points you will use to describe a building or structure on the board and lead learners to read them.; Describe the building you live in to learners using the points you have written on the board.; Let learners also give a description of buildings or a structure using the points on the board.', 430),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Descriptive Writing', 'B4.4.3.1', 'Exhibit the knowledge in writing of descriptive essays using controlled composition', 'B4.4.3.1.3', 'Describe objects within the environment on their own', 'Let learners mention some things in the environment.; Show a couple of objects to learners.; Use some words to describe the objects.; Encourage learners to describe objects within the environment on their own.', 440),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Persuasive Writing', 'B4.4.4.1', 'Exhibit knowledge and understanding of writing persuasive essays using controlled composition', 'B4.4.4.1.1', 'Write a persuasive essay on cleanliness using controlled composition', 'Let learners mention some actions that destroy the environment.; Discuss cleanliness with learners.; Allow the learners to talk with each other about cleanliness.; Let learners write a persuasive essay on cleanliness using controlled composition.', 450),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Persuasive Writing', 'B4.4.4.1', 'Exhibit knowledge and understanding of writing persuasive essays using controlled composition', 'B4.4.4.1.2', 'Compose a persuasive essay based on a picture description', 'Let learners mention some actions that destroy the environment.; Show learners some pictures.; Let learners describe the picture.; Lead learners to compose a persuasive essay based on a picture description.', 460),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Persuasive Writing', 'B4.4.4.1', 'Exhibit knowledge and understanding of writing persuasive essays using controlled composition', 'B4.4.4.1.3', 'Write a persuasive essay on responsibility', 'Let learners mention the names of their parents and friends.; Let learners tell you what they think are the responsibilities of their parents (you can touch on the responsibilities of other people as well).; Write a model persuasive essay with learners on the board.; Let learners write a persuasive essay on responsibility.', 470),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Argumentative Writing', 'B4.4.5.1', 'Show an understanding of recognising and writing argumentative essays', 'B4.4.5.1.1', 'Understand the process in writing good argumentative essays', 'Raise an issue and ask learners to tell you what they think about it.; Discuss what an argumentative writing is with learners.; Discuss the process of writing a good argumentative essay.; Group learners and let them write an argumentative essay on a given topic.; Let learners read their essays to the class and discuss the essays with learners.', 480),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Argumentative Writing', 'B4.4.5.1', 'Show an understanding of recognising and writing argumentative essays', 'B4.4.5.1.2', 'Write simple argumentative essays', 'Write a model argumentative essay with learners on the board.; Help learners to write simple argumentative essays in groups.; Let learners exchange their works.; Let group leaders read the essay on behalf of the group.; Discuss their essays with them.', 490),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Argumentative Writing', 'B4.4.5.1', 'Show an understanding of recognising and writing argumentative essays', 'B4.4.5.1.3', 'Write a simple argumentative essay on a given topic', 'Write a model argumentative essay with learners.; Help learners to write a simple argumentative essay on a given topic.; Allow learners to write argumentative essay on a given topic in groups.', 500),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Informative/Academic Writing', 'B4.4.6.1', 'Show an understanding of writing events of the day and editing it', 'B4.4.6.1.1', 'Write about personal experiences of the day', 'Narrate an experience you have had in life to learners.; Let learners also narrate an experience they have had in life before.; Let learners narrate an experience they have had in the day.; Help learners to write personal experience of the day.', 510),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Informative/Academic Writing', 'B4.4.6.1', 'Show an understanding of writing events of the day and editing it', 'B4.4.6.1.2', 'Write picture events', 'Let learners mention some things in the classroom.; Let learners cut out pictures from magazines.; Let them create a picture book.; With their own picture book, help learners to write picture events.', 520),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Informative/Academic Writing', 'B4.4.6.1', 'Show an understanding of writing events of the day and editing it', 'B4.4.6.1.3', 'Edit your writing', 'Give learners a topic.; Let learners write their own passage on the topic.; Let learners do peer editing of their own writings.', 530),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Literary Writing', 'B4.4.7.1', 'Demonstrate knowledge of writing poems, prose and plays', 'B4.4.7.1.1', 'Comprehend the process in writing poems, prose, and plays', 'Let learners sing a song they know.; Discuss with learners some features of plays, prose and poems.; Through discussion, encourage learners to comprehend the process in writing poems, prose and plays.', 540),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Literary Writing', 'B4.4.7.1', 'Demonstrate knowledge of writing poems, prose and plays', 'B4.4.7.1.2', 'Compose short poems using controlled composition', 'Let learners explore a rhyme they know.; Use a controlled composition to write a short poem on the board.; Let learners explore the poem with gestures.; In groups let learners compose short poems using controlled composition.', 550),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Literary Writing', 'B4.4.7.1', 'Demonstrate knowledge of writing poems, prose and plays', 'B4.4.7.1.3', 'Create short plays and stories using controlled composition', 'Let learners sing a familiar traditional song they know.; Use a controlled composition to create a short story or play with learners.; Put them in pairs and let them create short plays and stories using controlled composition.', 560),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Letter Writing', 'B4.4.8.1', 'Exhibit knowledge of writing good informal letters', 'B4.4.8.1.1', 'Discuss the process in writing good informal letters', 'Let learners say the letters of the alphabet.; Discuss with learners what an informal letter is.; Discuss with learners the process of writing a good informal letter.; Let them comprehend the process in writing good informal letters.; Discuss features of informal letters.', 570),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Letter Writing', 'B4.4.8.1', 'Exhibit knowledge of writing good informal letters', 'B4.4.8.1.2', 'Write informal letters using controlled composition', 'Write an informal letter on the board and lead learners to discuss it.; Let learners read the letter as a group and then individually.; Using the letter on the board as a guide let learners write an informal letter.', 580),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Letter Writing', 'B4.4.8.1', 'Exhibit knowledge of writing good informal letters', 'B4.4.8.1.3', 'Write good informal letters', 'Let learners say the letters of the alphabet.; Give learners a topic and let them write an informal letter on the topic in groups.; Let the groups present their essays to the class.; Let learners write an informal letter on their own.', 590),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B4.5.1.1', 'Exhibit knowledge of using capital letters appropriately', 'B4.5.1.1.1', 'Begin sentences with capital letters', 'Let learners write their names on a paper and show it to the class.; Create a game about using a capital letter to begin a sentence.; Play the game with learners.; Write the sentences on the board and let learners read the sentences.; Encourage learners to begin sentences with capital letters.', 600),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B4.5.1.1', 'Exhibit knowledge of using capital letters appropriately', 'B4.5.1.1.2', 'Use capital letters after full stops', 'Create a game about using a capital letter after a full stop.; Play the game with learners.; Let learners use capital letters after full stops.', 610),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Capitalization)', 'B4.5.1.1', 'Exhibit knowledge of using capital letters appropriately', 'B4.5.1.1.3', 'Demonstrate an understanding of the use of capital letters after colons', 'Create a game about using a capital letter after a colon.; Play the game with learners.; Help learners to understand the use of capital letters after a colon.; Encourage learners to use capital letters to begin a sentence after a colon.', 620),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B4.5.2.1', 'Demonstrate an understanding on the use of punctuation marks appropriately in writing sentences', 'B4.5.2.1.1', 'Demonstrate the use of commas', 'Use commas in sentences on the board.; Let learners demonstrate the use of commas by writing sentences in groups.; Let learners show their work to the class and discuss it with them.', 630),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B4.5.2.1', 'Demonstrate an understanding on the use of punctuation marks appropriately in writing sentences', 'B4.5.2.1.2', 'Write sentences using full stops appropriately', 'Write sentences on cardboards and show it to learners.; Let learners read the sentences as a group.; Call learners to put the full stop at the right positions in the sentences.; Let learners write sentences using full stops effectively.', 640),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Punctuation)', 'B4.5.2.1', 'Demonstrate an understanding on the use of punctuation marks appropriately in writing sentences', 'B4.5.2.1.3', 'Recognise and use the question marks appropriately in writing', 'Write questions on the board using question marks appropriately.; Encourage learners to recognize and use the question marks appropriately in writing.; Write a piece on the board and call learners to put in the correct punctuations.', 650),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of action words)', 'B4.5.3.1', 'Demonstrate knowledge on recognition and use of action words', 'B4.5.3.1.1', 'Write past tense action words', 'Revise the lesson on commands with learners.; Write sentences using past action words.; Lead learners to recognise the present tense action words in the sentences.; Let learners write past tense action words on their own.', 660),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of action words)', 'B4.5.3.1', 'Demonstrate knowledge on recognition and use of action words', 'B4.5.3.1.2', 'Recognise past tense action words in short sentences', 'Use past tense action words to write short sentences on the board.; Call learners to read the sentences.; Help learners to recognise past tense action words in the short sentences.; Allow learners to narrate what they did yesterday.; Let learners recognise the past tense action words in the narration.', 670),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of action words)', 'B4.5.3.1', 'Demonstrate knowledge on recognition and use of action words', 'B4.5.3.1.3', 'Use past tense action words in short sentences', 'With the learners’ contribution use past tense action words to write short sentences on the board.; Let learners read the sentences on the board.; Lead learners to recognise the past tense action words in the sentences.; Let learners use past tense action words in short sentences on their own and read aloud for other learners to recognise the past tense action word.; Let learners use the past tense action words to form sentences.', 680),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of qualifying words)', 'B4.5.4.1', 'Demonstrate knowledge on the use of adjectives and adverbs', 'B4.5.4.1.1', 'Recognise the positive comparative words and superlative words of regular adjectives', 'Let learners sing a familiar song.; In pairs, let learners compare their heights, sizes, nature, etc.; Help learners to recognise the words that are used to express comparative and superlative forms.', 690),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of qualifying words)', 'B4.5.4.1', 'Demonstrate knowledge on the use of adjectives and adverbs', 'B4.5.4.1.2', 'Differentiate between comparative and superlative words/adjectives', 'In pairs, let learners differentiate between the comparative and superlative words/adjectives. E.g. Better, best more beautiful, most beautiful', 700),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of qualifying words)', 'B4.5.4.1', 'Demonstrate knowledge on the use of adjectives and adverbs', 'B4.5.4.1.3', 'Use comparative and superlative words/adjectives in sentences', 'In groups let learners use comparative and superlative words/adjectives in sentences.; Assist learners to recognise comparative and superlative words/adjectives in sentences.; Let learners use these words to form sentences: more beautiful, most beautiful, e.g. Kofi is a better keeper but Ama is the best keeper.', 710),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of qualifying words)', 'B4.5.4.1', 'Demonstrate knowledge on the use of adjectives and adverbs', 'B4.5.4.1.4', 'Demonstrate the use of comparative and superlative adverbs /words', 'Let learners demonstrate the use of comparative and superlative words individually in class. E.g. better, best more beautiful, most beautiful.', 720),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of postpositions)', 'B4.5.5.1', 'Demonstrate knowledge in the use of postpositions', 'B4.5.5.1.1', 'Explore the use of other postpositions such as below and under in sentences', 'Let learners explore a poem.; Illustrate by putting an object above, below, etc. for learners to discuss where the object is.; Use postpositions to write phrases and sentences.; Guide learners to read the phrases and sentences as a group.; Guide learners to explore the use of other postpositions such as below and under in sentences.', 730),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of postpositions)', 'B4.5.5.1', 'Demonstrate knowledge in the use of postpositions', 'B4.5.5.1.2', 'Recognise and use other postpositions in sentences', 'Use postpositions to write phrases and sentences on the board.; Let learners read the sentences as a group and in pairs.; Let learners recognise postpositions in sentences.; Let learners form sentences using the postpositions.', 740),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of postpositions)', 'B4.5.5.1', 'Demonstrate knowledge in the use of postpositions', 'B4.5.5.1.3', 'Demonstrate the use of postpositions such as below and under in context', 'Write phrases and sentences leaving out the postpositions.; Let learners fill them with the correct postpositions.; Help learners to demonstrate the use of postpositions such as below and under in context.; Let learners form sentences using the postpositions discussed.', 750),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of simple and compound sentences)', 'B4.5.6.1', 'Exhibit knowledge of forming compound sentences in writing', 'B4.5.6.1.1', 'Form compound sentences from simple sentences', 'Let learners form simple sentences.; Let them read the sentences as a group.; Use simple sentences to form compound sentences on the board.; In groups, let learners form compound sentences from simple sentences.; Let learners present their sentences to the class.', 760),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of simple and compound sentences)', 'B4.5.6.1', 'Exhibit knowledge of forming compound sentences in writing', 'B4.5.6.1.2', 'Exhibit knowledge of different types of conjunctions in writing', 'Let learners form simple sentences and read them to the class.; Discuss conjunctions with learners.; Write some conjunctions on the board and lead learners to say them.; Use different types of conjunctions to form sentences.; Let learners form sentences using the conjunctions.; Let learners understand different types of conjunctions in writing.', 770),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (Use of simple and compound sentences)', 'B4.5.6.1', 'Exhibit knowledge of forming compound sentences in writing', 'B4.5.6.1.3', 'Form compound sentences with conjunctions', 'Use different types of conjunctions to form sentences.; In pairs, let learners form compound sentences with conjunctions and read their sentences to the class.', 780),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (spelling)', 'B4.5.7.1', 'Exhibit knowledge of recognising and spelling words correctly', 'B4.5.7.1.1', 'Write seven and eight letter words correctly', 'Let learners say the letters of the alphabet.; Introduce learners to vocabulary words in a passage.; Help learners to write seven and eight letter words correctly.', 790),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (spelling)', 'B4.5.7.1', 'Exhibit knowledge of recognising and spelling words correctly', 'B4.5.7.1.2', 'Fill in missing letters from words', 'Write some words on the board and lead learners to mention the words.; Let learners mention and spell the words as a group.; Call learners to mention the words individually.; Introduce learners to words that have missing letters.; Let students to fill in missing letters from words.', 800),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language (spelling)', 'B4.5.7.1', 'Exhibit knowledge of recognising and spelling words correctly', 'B4.5.7.1.3', 'Fill in missing words from a short passage', 'Let learners sing a familiar work song.; Write some words on the board and lead learners to pronounce the words.; Let learners pronounce the words individually.; Introduce learners to a short passage and lead learners to read the passage.; Dictate the first four sentences of the passage to learners to write.; Let learners exchange their works and discuss their works with them.', 810),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Writing Conventions/ Usage', 'Integrating Grammar in Written Language(Conjunctions)', 'B4.5.8.1', 'Apply the knowledge of conjunctions in writing', 'B4.5.8.1.1', 'Identify and use simple conjunctions - and, but, or, nor - to link', 'similar ideas, contrasting ideas, show choices/express alternatives; Introduce the conjunctions one at a time in context.; Elicit examples of sentences with conjunctions from learners.; Put on cards simple sentences. e.g. i. Esi is tall. Ama is short. ii. Esi is tall but Ama is short.; Use combination drill for learners to practise the use of conjunctions. e.g. i. Learner A: I bought a pen… ii. Learner B: I bought a pen and a notebook. iii. Learner C: I will eat fufu…… Learner D: I will eat fufu or kenkey.', 820),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Building the Love and Culture of Reading in Learners', 'B4.6.1.1', 'Exhibit knowledge of reading long stories from sources other than the class Readers, with correct intonation', 'B4.6.1.1.1', 'Read long stories aloud correctly', 'Do a model reading of a long story.; Allow learners to read aloud long stories correctly in groups and then individually.; B.4.6.2.1.1 Read long passages correctly. • Revise letters of the alphabet, using the alphabet song. • Do a model reading of a long passage. • Help learners to read long passages correctly.', 830),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Reading Texts, Poems, Narratives and Short Stories', 'B4.6.3.1', 'Demonstrate knowledge on reading materials other than the reader provided in class', 'B4.6.3.1.1', 'Read passages/stories from other materials with correct tone', 'Read short passages to learners.; Let learners read short passages from other materials with correct tone.; Lead learners to discuss what they read.', 840),
('Basic 4', 'Ghanaian Language', 'ghanaian language', 'Extensive Reading/Children Literature/Library', 'Reading Texts, Poems, Narratives and Short Stories', 'B4.6.3.1', 'Demonstrate knowledge on reading materials other than the reader provided in class', 'B4.6.3.1.2', 'Answer question on the passage/stories read', 'Read short passages to learners.; Let learners to read short passages on their own and answer questions on the passages read. B.4.6.3.1.3 Explore the meaning of unfamiliar words from context or dictionary.; Let learners read a text.; Let them mention and find the meaning of unfamiliar words from context or dictionary. B.4.6.3.1.4 Summarise the passage read in a few words.; Allow learners to read a text.; Let learners answer about questions based on the passage read.; Discuss the process of summarizing with learners.; Allow them to summarize the passage read in few words.', 850),
('Basic 4', 'History', 'history', 'History as a Subject', 'Why and How We Study HISTORY', 'B4.1.1.1', 'Show understanding of the importance of studying history', 'B4.1.1.1.1', 'Explain the importance of studying the history of Ghana. Enquiry route: How does history promote our identity as Ghanaians? How does history promote the survival of the ethnic groups? How does history promote national integration? How does history promote national pride and patriotism?', '1. Engage learners to discuss how history defines our identity as Ghanaians; 2. Role-play to show how history teaches us customs, values, traditions all of which ensure the survival of our nation.; 3. Role play how history can promote national pride, patriotism and integration', 10),
('Basic 4', 'History', 'history', 'History as a Subject', 'Why and How We Study HISTORY', 'B4.1.1.2', 'Understand the sources for writing history', 'B4.1.1.2.1', 'Identify the sources of history including archaeology, numismatics, oral tradition, wall paintings etc. Enquiry route: What are the sources of history? What historical knowledge are we likely to acquire from these sources?', '1. List the sources of history including funeral brochures, oral tradition, old photographs, old letters and diaries, arts and craft works, old newspapers, dirges, appellation and books.; 2. Classify these sources under primary and secondary sources.; 3. Explain how relevant historical information can we obtain from old newspapers and diaries? (E.g. Natural disasters – drought, bushfire etc.)', 20),
('Basic 4', 'History', 'history', 'History as a Subject', 'Major Historical Locations', 'B4.1.4.1', 'Demonstrate knowledge of the history of some historical locations in Ghana', 'B4.1.4.1.1', 'Describe the history of Ghana’s major historical locations, specifically, Flagstaff house, Burma camp, James Town light house, Gbewa Palace, Larabanga Mosque etc. Enquiry route: where could these historical locations be found? When were they built? Who built them? Why were they built? How have these historical locations changed overtime?', '1. With the use of internet, identify the major historical locations in Ghana (where they are located, who built them when and why they were built); 2. Explain some of the uses to which these historical locations have been put since they were built.; 3. Match these historical locations to where they can be located; 4. Show and discuss a documentary/ slides on these locations in Ghana; 5. Retell the stories behind some of the historical location including Flagstaff house, GBC, Burma camp, Kumasi military museum, Komfo Anokye Sword in Kumasi etc.', 30),
('Basic 4', 'History', 'history', 'My Country Ghana', 'The People Of Ghana', 'B4.2.1.1', 'Show understanding some of the factors that led to the rise, expansion and decline of one major kingdom', 'B4.2.1.1.1', 'Describe how one major Kingdom was formed and the reasons behind its expansion. Enquiry route: Where was this major Kingdom formed? How was it formed? How did it expand?', '1. Identify the reasons for the rise, expansion and decline of one Kingdom. Eg Savanna Belt States-Mole-Dagbani and Gonja Forest Belt States - Bono, Adansi, Asante, Denkyira and Akwamui. Coastal Belt States - The Anlo, The Fante, Ga-Adangme and Effutu; 2. Using the map of Ghana, locate where this major Kingdom is found.; 3. By animations, play games on location of major Kingdoms.', 40),
('Basic 4', 'History', 'history', 'My Country Ghana', 'The People Of Ghana', 'B4.2.1.1', 'Show understanding some of the factors that led to the rise, expansion and decline of one major kingdom', 'B4.2.1.1.2', 'State the factors that led to decline of the Kingdom you have studied. Enquiry routes: What factors led to the decline of the Kingdom?', '1. Give reasons why some of the Kingdoms declined. E.g. Internal disputes (rebellions, succession disputes), British interference, conquest by another kingdom, desire to expand territories – Akwamu’s location to the east of the Volta in 1733, Denkyira’s decline in 1701, Asante’s decline in 1874.', 50),
('Basic 4', 'History', 'history', 'My Country Ghana', 'Some Selected Individuals', 'B4.2.5.1', 'Demonstrate understanding of the role of significant traditional rulers in Ghana’s history', 'B4.2.5.1.1', 'Identify the role played by some traditional rulers in the national development including Dode Akaibi of Accra, Ndewura Jakpa of Gonja, Osei Tutu I of Asante, Gbewaa of Pusiga, Togbe Sri I., Sir Ofori Atta of Akim Abuakwa, Nana Kobina Nketsia I of Esikado etc. Enquiry route: Who were the traditional rulers who contribute to Ghana’s development? How did they contribute to Ghana’s development? Which traditional rulers inspires you most and why?', '1. Name some traditional chiefs and queen-mothers from the major ethnic groups and state the reasons why they are considered significant in Ghana’s history. Dode Akaibi of Accra, Ndewura Jakpa of Gonja, Osei Tutu I of Asante, Gbewaa of Pusiga , Nana Kobina Nketsia I of Esikado etc.; 2. Show photographs/ documentaries on the roles played by these traditional rulers in national development; 3. Retell the live story of any of these from a documentary show; 4. Identify the traditional rulers whose work inspires you most and give reasons for your choice', 60),
('Basic 4', 'History', 'history', 'Europeans in Ghana', 'Missionary Activities', 'B4.3.3.1', 'Demonstrate knowledge of Europeans’ engagement in other activities other than trade in Ghana', 'B4.3.3.1.1', 'Describe European missionary activities in Ghana Enquiry Route: Which European missionary society was the first to come to the Gold Coast? In which areas did they operate? What was their impact on the lives of Ghanaians?', '1. Identify the missionary societies that came to Ghana (starting from the first to the last); 2. Locate places where they operated (e.g. Basel-Akuapem, Bremen-Peki etc); 3. Discuss Christianity and formal education as some of the major impacts of European presence in Ghana; 4. Show and discuss video/documentary of European activities in Ghana; 5. Discuss other activities they engaged in (trade, vocational training centres, health facilities, development of alphabets for some local languages and translation of the Bible into local languages); 6. Debate the effects of European activities in Ghana', 70),
('Basic 4', 'History', 'history', 'Colonisation and Developments under Colonial Rule in Ghana', 'Establishing British Rule in Ghana', 'B4.4.1.1', 'Demonstrate understanding of the gradual process of colonisation and recall the initial steps the British took to colonise Ghana', 'B4.4.1.1.1', 'Examine the Bond of 1844 Enquiry route: Enquiry route: What led to the signing of the bond of 1844? Where was the Bond of 1844 signed? Which people signed? What was the significance of the Bond?', '1. Discuss events leading to the signing of the Bond of 1844.; 2. Using primary evidence provide students with the content of 1884 and discuss it with them; 3. With the use of the internet/pictures show the Palaver Hall where the Bond was signed; 4. Brainstorm the significance of the Bond of 1844?', 80),
('Basic 4', 'History', 'history', 'Colonisation and Developments under Colonial Rule in Ghana', 'Establishing British Rule in Ghana', 'B4.4.1.2', 'Show understanding of how the various parts of the country were brought together', 'B4.4.1.2.1', 'Describe how the different areas', '– The Colony, Asante, The Northern Territories and The British Mandated Togoland– became one territory known as the Gold Coast Enquiry route: What is colonisation? How different was a protectorate from a colony? how did Asante and the Northern Territories become protectorates of the British? How did Britain acquire the mandated territories?; 1. Define the term colonialism; 2. Role play on the role of George Ekem Ferguson in the acquisition of The Northern Territories.; 3. Illustrate how the Asante and the Northern Territories became protectorates with the aid of a map; 4. Locate the areas classified as British Togoland on a map; 5. Compare the map of the Gold Coast in 1955 and the map of Ghana, today. Discuss your observations', 90),
('Basic 4', 'History', 'history', 'Journey to Independence', 'The 1948 Riots And After', 'B4.5.3.1', 'Show understanding of the sequence of events leading to the 1948 riots in Ghana', 'B4.5.3.1.2', 'Examine sources of evidence about what happened during the 1948 riots. Enquiry routes: Who were the ex-service men? Who ordered the shooting of the ex- service men? Where did the shooting occur?', '1. Show a map of Accra indicating the routes that were approved for the ex-service men; 2. Use a documentary to illustrate what happened during the 1948 riots and discuss it afterwards; 3. Role play the scene of the 1948 riots as evidence for learners; 4. Discuss the arrest of the ‘Big Six’ (leaders of the UGCC)', 100),
('Basic 4', 'History', 'history', 'Independent Ghana', 'The Republics', 'B4.6.1.1', 'Understand that there have been four Republics in Ghana', 'B4.6.1.1.1', 'Explain that Ghana up to June 1960, though independent, had the Queen of The United Kingdom (UK) as Head of State of the Ghana and made limitations on Ghana’s independence. Enquiry route: What is a Republic? Who was the leader of Ghana’s first Republic? What were the limitations to Ghana’s independence until 1960?', '1. Define the term Republic?; 2. Discuss the limitations on Ghana’s independence up to June 1960; 3. Use the internet identify the positions controlled by British officials up to June 1960', 110),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit whole numerals up to 100,000', 'B4.1.1.1.1', 'Model number quantities, place value for multi-digit using graph sheets or multi-base materials up to 100,000 E.g.1. Ask learners to model number quantities up to 100,000 using graph sheets or multi-base materials', 'For instance, with multi-base block , a cube = 100 unit; a rod = 1000; a flat = 10,000 and a block = 100,000; learners model 32,300 with the appropriate materials E.g.2 Ask learners to model the number 12,500 shading graph sheet square as shown below, where 2cm×2cm square represents 10 units.', 10),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit whole numerals up to 100,000', 'B4.1.1.1.2', 'Read and write numbers in figures and in words up 100,000', 'E.g. 1 Play the place value number wheel game: Use the hundred thousand number wheel to generate 6-digit numbers and represent the number generated on a place value frame. Throw a number of pebbles (or stones) onto the number wheel, identify the number of pebbles landing in each place value ring, and state the number generated in the wheel (i.e. 2 landed in the ten-thousand’ ring making the number twenty-thousand or 20,000). NB: The representations to use also include verbal, and numerals. Learners must match number word cards to the figures', 20),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit whole numerals up to 100,000', 'B4.1.1.1.3', 'Identify numbers in different positions around a given number in a number chart', 'E.g. 1 Display a number chart in multiples of 500 between 10,000 and 100,000 and lead learners identify numbers in different positions around a given number. Put learners in pairs and give each group a number grid and have them identify numbers in different positions around a chosen number. 10,000 10,500 11,000 11,500 12,000 12,500 20,000 20,500 21,000 21,500 22,000 22,500 30,000 30,500 31,000 31,500 32,000 32,500 40,000 40,500 41,000 41,500 42,000 42,500 50,000 50,500 51,000 51,500 52,000 52,500 60,000 60,500 61,000 61,500 62,000 62,500', 30),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit whole numerals up to 100,000', 'B4.1.1.1.4', 'Compare and order whole numbers up to 10,000 and represent comparisons using the symbols “<”, “=”, “>”', 'E.g. 1 Learners identify numbers which are 1,000 and 10,000 more or less than a given five-digit or six-digit number. E.g. 2400 is 1,000 less than 3400. Learners use words such as: “equal to” “greater than” “less than” and later use symbols such as “<”, “=”, “>” to compare numbers up to 100,000 taking into consideration the place value of each digit in the given number. E.g. 1200 = 1200; 27345 > 26355, E.g. 2 Learners work together in their groups to order a given set of numbers in ascending or descending order verbally and in writing. E.g. 1020,1025, 2673,2873, E.g. 3 Give two numbers between 10,000 and 100,000 to each group and encourage learners to say as many things as possible about the two numbers. For instance, 21345 and 21534; 21345 is less than (smaller than) than 21534 or 21534 is bigger than (greater than) 21345, or 21345 is almost 200 less than 21534 etc.', 40),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit whole numerals up to 100,000', 'B4.1.1.1.5', 'Round (off, up, down) whole numbers up to 10000 to the nearest, thousands, hundreds and tens', 'E.g. 1 Learners round off numbers to the nearest 1000, 100 and; 10. For instance; 9500 is approximately 10,000 and 9100 as approximately 9,000 E.g. 2 Learners round up and round down to estimate sums and differences NB: To round down learners consider the smaller of the two approximated numbers, while round up considers the bigger of the two numbers. The table below may bring the meaning of these two concepts clearer 14765 Round up Round down Round off to the nearest ten 14970 14760 14970 to the nearest hundred 14800 14700 14800 to the nearest thousand 15000 14000 15000 E.g. 3 Learners work together to round up and round down to estimate sums and differences. For instance. as approximately 400 because is 2 3 0  1 6 0 2 3 0 approximately while is approximately , therefore 200 1 6 0 2 0 0 200200 400', 50),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.1', 'Demonstrate an understanding of quantities and place value for multi-digit whole numerals up to 100,000', 'B4.1.1.1.6', 'Skip count forwards and backwards in 50s and 100s up to and from 10000', 'E.g. 1 Put learners into convenient groups. A learner mentions a number and another makes skip count in 50s or 100s to include the fifth count. For instance. Learner 1: Shout out “240” …. Learner 2: 290, 340, 390, 440, 490, etc. Learner 3; Shout out “1285” skip counting down in 100s Learner 4; 1185, 1085, 985, 885, 785….etc. E.g. 1 Skip count forwards and backwards by 50s and between 1000 and 10000 that are multiples of 50s and 100s but make an error or leave out a number. Challenge learners to identify or correct error', 60),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.2', 'Demonstrate understanding of Roman numerals up XXX (30)', 'B4.1.1.2.1', 'Develop an understanding of Roman Numeral system up XXX (i.e. 30)', 'E.g. 1 Display Roman numeral charts (1-30) arranged in sequential order and lead learners to identify the numerals. Learners identify the main characters of the roman numerals used to build the table up to 30 i.e. I, II, III, IV, V, X, Call out a numeral and have learners point at it from the chart E.g. 2 Have learners match the Roman numerals to the Hindu-Arabic numerals for instance I = 1; V= 5: X= 10, XV=; 15. Mention some numerals randomly and have learners point at it on the chart', 70),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.2', 'Demonstrate understanding of Roman numerals up XXX (30)', 'B4.1.1.2.2', 'Count and convert Hindu Arabic numerals to Roman numerals up to 30 and vice versa', 'E.g. 1 Learners read the chart sequentially forwards and backwards, vertically (up and down), zig-zag, diagonally and randomly without pointing to the numbers. Invite 2-3 learners to read to the class. Call a Roman numeral and ask learners to write E.g. 2 Give learners a numeral in the Hindu Arabic system and have learners convert to roman numeration and vice versa for instance XXIV = 24', 80),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.3', 'Demonstrate an understanding of factors, multiples and squared numbers', 'B4.1.1.3.1', 'Determine set of factors of a given numbers up to 50', 'E.g. 1 Learners make formation of sets of equal object from a given quantity. For example with 12 straws Learners make groupings such as: 3 𝑔𝑟𝑜𝑢𝑝𝑠 𝑜𝑓 4 ⇒3,4 4 𝑔𝑟𝑜𝑢𝑝𝑠 𝑜𝑓 3 ⇒4,3 2 𝑔𝑟𝑜𝑢𝑝𝑠 𝑜𝑓 6 ⇒2,6 E.g. 2 Learners pair grouping and the number of equal objects for each formation as factors; 4 groups of 3 straws (4,; 3) 3 groups of 4 straws (3,; 4) 6 groups of 2 straws (6,; 2) 2 groups of 6 straws (2,; 6) 1 group of 12 straws (1,; 12) 12 groups of 1 straw (12,; 1) E.g. 3 Learners collect from the pairs and form a set as the factors of the given number. For example the set of factors of 12 = {1,2,3,4,6,12}', 90),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.3', 'Demonstrate an understanding of factors, multiples and squared numbers', 'B4.1.1.3.2', 'Determine the highest common factor (HCF) of any two whole numbers between 1 and 50', 'E.g. 1 Learners list the factors of two or more given whole numbers; 12 and 24 to list the factors. That is: 12 = {1,2,3,4,6,12}𝑎𝑛𝑑 24 = {1,2,3,4,6,8,12,24} Learners determine the set of the common factors E.g. The common set factors of 12 and 24 = 1,2,3,4,6,12 Learners select the highest common factor of 12 and 24 as 12 . E.g. 2 Learners may use Venn diagrams to find the common factors and then the highest common factor by placing the factors in the regions of the shapes. The highest common factor of 12 and 20, in the diagram is 4 Note: Do not introduce formal set theory and notation. Numbers in the common regions of the two shapes.', 100),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.3', 'Demonstrate an understanding of factors, multiples and squared numbers', 'B4.1.1.3.3', 'Determine the lowest common multiple (LCM) of at least any two given numbers up to 100', 'E.g. 1 Learners identify and the list the set multiples of given numbers using skip counting E.g. The set of multiples 5 = { 5, 10 15……..100} and the etc. of multiples of 10 = {10, 20, 30 , ……..100} E.g. 2 Learners list the set of common multiples of any two or more given numbers between 0 and 100. E.g. The set of common multiples of 5 and 10 ={10, 20, 30, … 100}. Learners select the least of the common multiple of the given numbers, and identify the least common multiple (LCM). The LCM of 5 and 10 is 10.', 110),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.3', 'Demonstrate an understanding of factors, multiples and squared numbers', 'B4.1.1.3.4', 'Recognise the relationship between factors and multiples', 'E.g. 1 Factors represent the numbers that we can multiply to get a bigger number called the product or multiple. Since12 = 4×3, we can say 4 and 3 are factors of 12; and 12 is a multiple of 3 or a multiple of; 4. Break given multiples into factors and pairs of factors of given numbers. E.g. 2 Investigate even and odd numbers. E.g. 3 Investigate numbers that are multiples of 2, 3, 4 and; 5. How do you know a number is a multiple of 2? a multiple of 3? a multiple of 4? and a multiple of 5? (This is also known as the divisibility test).', 120),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.3', 'Demonstrate an understanding of factors, multiples and squared numbers', 'B4.1.1.3.5', 'Generate and analyse patterns in square numbers', 'E.g. 1 Put learners into convenient groups and provide each group adequate number of bottle tops, an A4 sheet and a 30cm ruler and ask them to generate square numbers by continuing the arrangement shown below up to the 10th number; [i.e. 1, 4, 9, 16, 25, 36 … ) 1 4 9 16 ………………………', 130),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.3', 'Demonstrate an understanding of factors, multiples and squared numbers', 'B4.1.1.3.6', 'Represent square numbers using factors', 'E.g. 1 Learners draw a square whose side is 1 unit by 1 unit and determine the area; repeat the activity for a 2 unit, 3 unit and 4 unit squares. E.g. 2 Learners work in groups to continue the pattern to include the factors of 144. (Key Concept: when a number has been multiplied by itself we say the answer is a square number hence 1×𝟏 = 𝟏;𝟐×𝟐 = 𝟒; 𝟑×𝟑 = 𝟗 and we can write three squared as 𝟑×𝟑 = 𝟑𝟐 )', 140),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.4', 'Interpret negative and positive numbers in context', 'B4.1.1.4.1', 'Describe real life situations using positive and negative values', 'E.g. 1 Brainstorm learners on happenings which may be represented with positive and negative numbers (e.g. having savings with a bank and owing a bank; profit and loss etc.) Movement on the number line to the right and left of zero', 150),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Counting, Representation & Cardinality', 'B4.1.1.4', 'Interpret negative and positive numbers in context', 'B4.1.1.4.2', 'Count forwards and backwards with positive and negative whole numbers through zero', 'E.g. 1 Learners count from a given interval of positive and negative numbers on the number line. For example, count from 10 backward through zero to negative -8.', 160),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B4.1.2.1', 'Recall basic multiplication fact up to 𝟏𝟐×𝟏𝟐', 'B4.1.2.1.1', 'Determine basic multiplication facts up to 𝟏𝟐×𝟏𝟐', 'E.g.; 1. To find 2×3 = ? Learners arrange 2 straws vertically (legs) and put across it with 3 horizontal ones (arms). Learners count the number of intersections E.g.; 2. Learners model different multiplication sentences, for example 3×4. Learners mention the number of dots (intersections) for other learners to model fence Note: Alternatively, learners may draw vertical lines to represent the legs and horizontal lines across them to represent the arms and then count the number of intersections as the product E.g.; 3. Draw a 6 by 6 multiplication chart for the numbers 5 to 10 and use it as a game board to play the 3-in-a-line game with a pair of dice or playing cards. Players take turns in throwing a pair of dice and mark (or cover) the product made in a throw with his/her marker (or counter). The winner is the one who obtains three products in a line. E.g.; 4. Learners find doubles of given numbers; find squares of given numbers; and skip count in 4, 5, and 8', 170),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B4.1.2.2', 'Describe and apply mental mathematics strategies and number properties to determine answers for basic multiplication facts to 81 and related division facts', 'B4.1.2.2.1', 'Apply mental mathematics strategies and number properties, such as skip counting from a known fact using doubling or halving using patterns in the 9s facts using repeated doubling or halving to determine answers for basic multiplication facts to 81 and related division facts', 'E.g. 1 Describe the mental mathematics strategies used to determine a given basic fact, such as  skip count up by one or two groups from a known fact (e.g., if 5 × 7 = 35, then 6 × 7 is equal to 35 + 7 and 7 × 7 is equal to 35 + 7 +; 7)  skip count down by one or two groups from a known fact (e.g., if 8 × 8 = 64, then 7 × 8 is equal to 64 – 8 and 6 × 8 is equal to 64 – 8 –; 8)  doubling (e.g., for 8 × 3 think 4 × 3 = 12, and 8 × 3 = 12 +; 12)  patterns when multiplying by 9 (e.g., for 9 × 6, think 10 × 6 = 60, and 60 – 6 = 54; for 7 × 9, think 7 × 10 = 70, and 70 – 7 =; 63)  repeated doubling (e.g., if 2 × 6 is equal to 12, then 4 × 6 is equal to 24 and 8 × 6 is equal to; 48)  repeated halving (e.g., for 60 ÷ 4, think 60 ÷ 2 = 30 and 30 ÷ 2 =; 15)  relating division to multiplication (e.g., for 64 ÷ 8, think 8 × … =; 64) E.g. 2 Recall multiplication facts to 81 and related division facts', 180),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B4.1.2.2', 'Describe and apply mental mathematics strategies and number properties to determine answers for basic multiplication facts to 81 and related division facts', 'B4.1.2.2.2', 'Apply mental mathematics strategies for multiplication, such as annexing then adding zero halving and doubling using the distributive property', 'E.g. 1 Determine the products when one factor is a multiple of 10, 100, or 1000 by annexing zero or adding zeros (e.g., for 3×200 think of 3×2 and then add two zeros) E.g. 2 Apply halving and doubling when determining a given product (e.g., 32×5 is the same as 16×10) E.g. 3 Apply the distributive property to determine a given product involving multiplying factors that are close to multiples of 10 (e.g., 29×7 = (30×7) – (1×7) = 203', 190),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B4.1.2.3', 'Describe and apply mental mathematics strategies and number properties to determine answers for basic multiplication facts to 81 and related division facts CONT’D B4.1.2.3 Demonstrate an understanding of multiplication (2 or 3- digit by 1-digit )', 'B4.1.2.3.1', 'Multiply multi-digit numbers efficiently', 'E.g.; 1. Multiplication of whole numbers using the “expand and box” method (partial decomposition method). Lead learners to multiply a 3-digit number by a 1-digit number as shown below, for example 448 ×2 =? × 400 40 8 2 800 80 16 448 ×2 = (400×2)+(40×2)+(8×2) = 800+80+16 = 800+80+(10+6) = 800+90+6 = 896 E.g.; 2. Multiplication of whole numbers using the lattice method. Have learners draw a 2 by 1 rectangular box for solving 54 ×; 3. E.g.; 3. Have learners draw a 2 by 2 rectangular box for solving 34 × 17.', 200),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B4.1.2.4', 'Recall basic division fact up to 100 B4.1.2.5 Demonstrate an understanding of division (2- or 3-digit by one digit number)', 'B4.1.2.4.1', 'Determine basic division fact up to 81', 'E.g.; 1. Investigate numbers that are multiples of 2, 3, 4 and; 5. How do you know a number is divisible by 2, 3, 4 and 5 (This is also known as the divisibility test). E.g.; 2. Draw a 6 by 6 multiplication chart and use it as a game board to play the 3-in-a-line game with a pair of dice or playing cards. Players take turns in throwing a one dice and mark (or cover) a number that can be divided by the results (i.e. a quotient). The winner is the one who obtains three numbers in a line.', 210),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B4.1.2.5', 'Recall basic division fact up to 100 B4.1.2.5 Demonstrate an understanding of division (2- or 3-digit by one digit number)', 'B4.1.2.5.1', 'Divide 2-digit numbers by 1-digit number efficiently', 'E.g.; 1. Division as repeated subtraction (using the long division method). Explain division as a way of repeatedly subtracting a divisor number from a given dividend until there is none left and then determining the number of times the divisor is taken from the dividend. For example, 25 ÷5 = ? Learners count the number of times 5 was subtracted from 25, which is 5 times. Hence, 𝟐𝟓÷𝟓 = 𝟓', 220),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Number Operations', 'B4.1.2.6', 'Translate and solve word problems involving the four basic operations on whole numbers', 'B4.1.2.6.1', 'Solve multi-step word problems involving the four basic operations', 'E.g.; 1. Learners model mathematical statements from a given word problem involving addition and multiplication and solve using the strategies learnt E.g.; 2. Learners model mathematical statements from a given word problem involving division and subtraction and solve using the strategies learnt E.g.; 3. Learners role play a given word problem involving addition and multiplication and solve E.g.; 4. Learners role play a given word problem involving subtraction and division and solve E.g.; 5. Learners model mathematical statements from a given word problem involving division and multiplication and solve using the strategies learnt The relationship between operations and the use of calculator and spreadsheet to assess the reasonableness of answers should be stressed', 230),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.3.1', 'Develop an understanding of equivalent and improper fractions 𝟏𝟐×𝟏𝟐', 'B4.1.3.1.1', 'Generate unit fractions and locate a unit fraction,', 'e.g. one-eighth, on a number line by defining the interval from 0 to 1 as the whole and partitioning it into 8 equal 𝟏 parts and that each part has size . 𝟖 E.g.; 1. Use number line to locate one eight by defining the interval from 0 to 1 as the whole and partitioning it into 8 equal parts E.g.; 2. Ask pupils to draw several lines, 30 units each, and mark the ends 0 and; 1. For each line ask them 1 1 1 1 1 , , , , to partition the interval from 0 to 1 into each of the following unit fractions and . 2 3 5 6 10 E.g.; 3. Ask pupils to use the number chart they have drawn 1 2 = = to read fractions that are equivalent e.g. 3 6 3 … 6 .', 240),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.3.1', 'Develop an understanding of equivalent and improper fractions 𝟏𝟐×𝟏𝟐', 'B4.1.3.1.2', 'Recognise and name equivalent fractions using pictorial representations and number line to determine the Lowest Common Denominator (LCD)', 'E.g.; 1. Use fraction chart to illustrate the concept of equivalent fractions (i.e. equal fractions that have different fractional units or denominators) i.e. one-half is 2-fourths, 3-sixth or 4-eighths. E.g.; 2. Illustrate the relationship between fractions and their equivalences by observing the different fractional units or denominators (i.e. the numerator is multiplied by the number of units the denominator is further broken into) E.g.; 3. Ask pupils to colour fractions that are equivalent to given fractions or write more equivalent fractions for give n fractions E.g.; 4. To determine the equivalent fractions of given fractions, find the Lowest Common Denominator (LCD) and use this to express the equivalent fractions that are comparable', 250),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.3.1', 'Develop an understanding of equivalent and improper fractions 𝟏𝟐×𝟏𝟐', 'B4.1.3.1.3', 'Find the simplest form of given fractions by dividing through by the highest common factor (i.e. by cancelling through by factors)', 'E.g.; 1. Use pictorial representations to illustrate the simplest form of a 6 3 1 = fraction; e.g. = 12 6 2 E.g.; 2. Find the simplest form of a given fraction, divide through by the highest common factor. E.g.; 3. Find the simplest form of a given fraction, express the numerator and denominators as factors and cancel through common factors. E.g.; 2. Find the simplest form of a given fraction, divide through by the highest common factor.', 260),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.3.1', 'Develop an understanding of equivalent and improper fractions 𝟏𝟐×𝟏𝟐', 'B4.1.3.1.4', 'Recognise fractions that are greater than one (i.e. improper fractions), draw and label such fractions with their symbols', 'E.g.; 1. Use several pictorial representations (or card cut outs) to introduce improper fractions (i.e. where the fraction is bigger than 1 or the numerator in larger than the 9 7 denominator). Examples are and (i.e. nine-fourths and 4 6 1 1 seven-sixths) and show how they are expressed as mixed fractions (i.e. 2 and 1 ). Ask pupils to 4 6 change given improper fractions to mixed fractions E.g.; 2. Ask pupils to express given coloured mixed fractions as improper fractions or draw and colour given improper fraction (e.g. seven- fourths, eleven-eights, etc.) E.g.; 3. Use number line to present more mixed fractions for pupils to identify and state their improper fractions', 270),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.3.2', 'Demonstrate an understanding of strategies for comparing, adding and subtracting fractions (same denominator, or one being a multiple of the others)', 'B4.1.3.2.1', 'Compare and order fractions with like denominators by using pictorial representations and finding equivalent fractions using the Lowest Common Denominator (LCD)', 'E.g.; 1. Use number line or fraction chart to illustrate the concept of comparable fractional units or denominators; i.e. halves, fourths and eighths are comparable; i.e. half can be changed to equivalent fractions in fourths and eighths, and fourths can changed to eighths. Also thirds can changed to sixths. 5 3 3 E.g.; 2. Use number line or fraction charts to compare and order unit fractions. Which is larger, and or 8 4 6 4 3 2 5 and ? Arrange from smallest to largest, , and 8 4 3 6 3 2 5 E.g.; 3. To arrange the fractions, , and , from largest to smallest, find the Lowest Common Denominator 4 3 6 (LCD) and use this to express the equivalent fractions', 280),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.3.2', 'Demonstrate an understanding of strategies for comparing, adding and subtracting fractions (same denominator, or one being a multiple of the others)', 'B4.1.3.2.3', 'Provide examples of where fractions are used', 'E.g.; 1. Discuss the contexts below in which fractions are used in real life and provide materials for pupils to act them out  Selling liquids – oil, kerosene, drinks, etc.  Sharing pizza or birthday cake - half, quarter, eighths, etc.  Buying objects in packets – egg, drinks, (half crate),  Buying cloth for sewing dresses – half, one-fourths or quarter, etc. E.g.; 2. Tell the time by half/quarter past, and half/quarter to. Draw clock-faces with times (i.e. half/quarter past or to) for pupils to read the time E.g.; 3. Drawing circle graphs that represent halves, fourths and eighths. The graph shows the ages of pupils in Primary; 4. If there are 40 pupils in the class, ask questions for pupils to interpret the graph', 290),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.4.1', 'Develop an understanding of decimals (tenths and hundredths) using concrete and pictorial representations and write decimal fractions as base ten numbers with place value', 'B4.1.4.1.1', 'Describe and represent decimals (tenths and hundredths) concretely, pictorially, and symbolically', 'E.g.; 1. Use pictorial representations or number line to revise tenths and hundredths and ask pupils to identify the fractions (i.e. A, B, C, D, & E). E.g.; 2. Use the tenth and hundredth place value chart to illustrate how to write the fraction as a base ten number with the introduction of the decimal point “∙” after ones place in the place value chart. E.g.; 3. Give pupils several common fractions (including Tenth and Hundredth Place improper fractions) to convert into tenths and Value Chart 1 𝟏 𝟏 hundredths and write their decimal names. 𝒔 𝒔 Fraction s ∙ 𝟏𝟎 𝟏𝟎𝟎 2  E.g. 7 = = . 1 25 5 10 A = 0 ∙ 1 4 100 1 125 B = 0 ∙ 2 0 8 1000 1 C 2 = 0 ∙ 5 2 3 D 3 = 0 ∙ 5', 300),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.4.1', 'Develop an understanding of decimals (tenths and hundredths) using concrete and pictorial representations and write decimal fractions as base ten numbers with place value', 'B4.1.4.1.2', 'Round decimals to the nearest tenth', 'E.g.; 1. Explain the rule for of rounding decimals, which is similar to that of rounding whole numbers. That is, rounding to the nearest tenth means that the rounded figure has one digit after the decimal mark. Rounding to the nearest hundredth means that the rounded figure has two digits after the decimal mark E.g.; 2. Use a table with several decimals fractions and explain the rule for of rounding decimals. Give pupils a table of decimal fractions to round to the nearest tenths or hundredths E.g.; 3. Ask students to change fractions to decimal writing their results to the nearest tenths or hundredths Round to Fraction Nearest Result 1 A 0.38 0.4 10 1 B 4.085 10 1 C 56.584 10 1 D 18.096 100 1 E 30.084 100', 310),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.4.1', 'Develop an understanding of decimals (tenths and hundredths) using concrete and pictorial representations and write decimal fractions as base ten numbers with place value', 'B4.1.4.1.3', 'Use models to explain the result of addition and subtraction of decimals (up to hundredths) 64 39 64+39 103', 'E.g.; 1. To add 0.64 and 0.39, means sum + which is = = 1.03. 100 100 100 100 That is, since both are hundredths fractions (i.e. have 2 decimal places) we can line up the decimal points to align the place values and add as whole numbers E.g.; 2. To add 0.6 and 0.39, one number is in tenths and other is in hundredths (i.e. one has 1 decimal place and the other 2 decimal places) it is important to line up the decimal points to align the place values and add as whole numbers 139 6 139 60 139− 60 79 E.g.; 3. To subtract 0.6 from 1.39, means − = − = = = 0.79. That is, 100 10 100 100 100 100 since one number is in tenths and other is in hundredths (i.e. one has 1 decimal place and the other 2 decimal places) it is important to line up the decimal points to align the place values and subtract as whole numbers.', 320),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.5.1', 'Demonstrate an understanding of percent (limited to whole numbers) concretely, pictorially, and symbolically)', 'B4.1.5.1.1', 'Model or recognise percent (as a fraction related to hundredths) using concrete models, pictorial representations and number line', 'E.g.; 1. Use several pictorial representations or number line to introduce tenths and hundredths and ask pupils to identify the fractions (i.e. A, B, C, D, & E). E.g.; 2. Use long division method to convert and write fractions as decimals in the number chart. E.g.; 3. Give pupils several common fractions 2 (including improper fractions) to Fractio Decimal convert into hundredths and write their n Places Percent decimal names or use long division; e.g. 1 A 0.10 10% 3 75 10 = = 75%. 4 100 43 B 0.43 43% 100 C 0.50 D 0.35 E F ⋮', 330),
('Basic 4', 'Mathematics', 'maths', 'Number', 'Fractions', 'B4.1.5.1', 'Demonstrate an understanding of percent (limited to whole numbers) concretely, pictorially, and symbolically)', 'B4.1.5.1.2', 'Compare and order a mixture of common, decimal and percent fractions (up to hundredths)', 'E.g.; 1. To compare and order a mixture of common, decimal and percent fractions, express them in one 4 form (i.e. either common, decimal or percent); e.g. to order ’ 0.78 and 85% (i) we can express 5 4 80 78 85 all as decimals → = ; 0.78 and 85% , hence the order from least to the 5 100 100 100 4 4 80 largest is 0.78, and 85%; (ii) we can also express all as percentages → = = 80%, 0.78 5 5 100 79 85 4 = 79%, and = 85%, hence the order from least to the largest is 0.78, and 85%. 100 100 5 E.g.; 2. To compare and order a mixture of common, decimal and percent fractions you can locate the fractions on the number and order them.', 340),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B4.2.1.1', 'Demonstrate an understanding of how to identify and describe patterns found in tables and charts, including a multiplication chart', 'B4.2.1.1.1', 'Describe the pattern found in a given table or chart', 'E.g.; 1. Using a hundred chart, ask students to colour each number as they skip count by 2s and describe the pattern created. Repeat for 3, 4, 5, 6, 7, 8, and; 9. Ask students to describe what changes they notice as the numbers increase. Note to what extent students: (i) identify all, some or none of the multiples of a given number. (ii) are able to predict and extend the pattern. (iii) are able to describe the pattern by relating it to similar designs in the real world (e.g., students may say it looks like a checker board)', 350),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B4.2.1.1', 'Demonstrate an understanding of how to identify and describe patterns found in tables and charts, including a multiplication chart', 'B4.2.1.1.2', 'Determine the missing element(s) in a given table or chart', 'E.g.; 1. Provide students with a chart with missing numbers and ask them to identify the missing numbers and explain their reasoning', 360),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B4.2.1.1', 'Demonstrate an understanding of how to identify and describe patterns found in tables and charts, including a multiplication chart', 'B4.2.1.1.3', 'Identify the error(s) in a given table or chart', 'E.g.; 1. Provide a mapping table containing errors. Ask students to Number of Number of identify and explain where the pattern has errors Tables Chairs 1 4 2 8 3 12 4 18 5 20 6 24', 370),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B4.2.1.2', 'Translate among different representations of a pattern, such as a table, a chart or concrete material', 'B4.2.1.2.1', 'Create a concrete representation of a given pattern displayed in a table or chart', 'E.g.; 1. Provide a table showing a pattern (involving one operation) such as the one below. Students can complete the table and create a concrete representation using linking cubes or other manipulatives Figure 1 2 3 4 5 6 7 8 Number of Cubes 3 6 9 ? ? ? ? ?', 380),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B4.2.1.2', 'Translate among different representations of a pattern, such as a table, a chart or concrete material', 'B4.2.1.2.2', 'Create a table or chart from a given concrete representation of a pattern', 'E.g. Present learners with a geometric design series, such as the one shown below. Ask them to extend the pattern and record it in a T-chart. Ask learners what the 10th step would be. What would the 12th step be? What would the 20th step be? #1 #2 #3 #4 Design # # of Square 1 1 2 2 3 3 4 4', 390),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B4.2.1.3', 'Represent, describe and extend patterns and relationships, using charts and tables, to solve problems', 'B4.2.1.3.1', 'Translate the information in a given problem into a table or char A B', 'E.g.; 1. Given the numerical pattern, ask students to extend the pattern 1 2 and explain how they determined the pattern and its missing 2 4 elements 3 4 8 E.g.; 2. Ask students to use manipulatives to represent this pattern and describe the relationship between the chart and the concrete representations', 400),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Patterns and Relationships', 'B4.2.1.3', 'Represent, describe and extend patterns and relationships, using charts and tables, to solve problems', 'B4.2.1.3.2', 'Identify and extend the patterns in a table or chart to solve a given problem', 'E.g.; 1. Give students two tables with patterns that are related in some way. Students should first extend each one by three more numbers. Then they should explain how the two patterns are alike and how they are different Pattern A Pattern B 1 5 1 2 E.g.; 2. Students could make up their own pairs of 2 10 2 7 patterns and challenge other students to 3 15 3 12 discover how they are alike and how they are 4 20 4 17 different 5 25 5 22', 410),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.1', 'Express a given problem as an equation in which a symbol is used to represent an unknown number', 'B4.2.2.1.1', 'Write a given problem as an equation in which a symbol is used to represent an unknown number', 'E.g.; 1. Ask students to explain the purpose of the box symbol in the following equation: 15 –  = 8', 420),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.1', 'Express a given problem as an equation in which a symbol is used to represent an unknown number', 'B4.2.2.1.2', 'Express a given pictorial or concrete representation of an equation in symbolic form', 'E.g.; 1. Provide a pictorial representation of the following and ask students to write equations with unknowns for each situation. Students need not solve their equations. (i) The perimeter of a triangle is 12 cm. One side is 3 cm and another side is 4 cm. What is the length of the third side? (ii) Mansa has three types of stickers. She has 25 stickers, 3 are Cocoa stickers and 18 are Cashew stickers. How many of the third type does she have? (iii) Kojo’s age and his sister’s age add up to; 18. If Kojo is 12, how old is his sister?', 430),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.2', 'Solve one-step equations involving a symbol to represent an unknown number', 'B4.2.2.2.1', 'Solve a given one-step equation using manipulatives', 'E.g.; 1. Ask students to solve the following using a pan balance: (i) 7 +  = 12 (ii) 19 –  = 11', 440),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.2', 'Solve one-step equations involving a symbol to represent an unknown number', 'B4.2.2.2.2', 'Describe orally, the meaning of a given one-step equation with one unknown', 'E.g.; 1. Ask students to solve the following equations and explain their thinking. (i)  – 13 = 20 (ii) 25 +  = 100', 450),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.2', 'Solve one-step equations involving a symbol to represent an unknown number', 'B4.2.2.2.3', 'Solve a given equation when the unknown is on the left or right side of the equation', 'E.g.; 1. Ask students to solve the following using base ten materials: (i) 109 +  = 164 (ii)  – 50 = 150', 460),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.2', 'Solve one-step equations involving a symbol to represent an unknown number', 'B4.2.2.2.4', 'Solve a given one-step equation using “guess and check”', 'E.g.; 1. Ask students to explain what the represents in the number sentences shown. Ask them to place numbers in the symbols to make the number sentence true.  - 7 = 6 9 +  = 17', 470),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.2', 'Solve one-step equations involving a symbol to represent an unknown number', 'B4.2.2.2.5', 'Identify the unknown in a problem, represent the problem with an equation, and solve the problem concretely, pictorially or symbolically', 'E.g.; 1. Provide students with linking cubes to model situations. Pose the problem: Kobby has 13 red marbles and 22 blue marbles. How many more blue marbles than red marbles does Kobby have? Observe how students solve the problem', 480),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.2', 'Solve one-step equations involving a symbol to represent an unknown number', 'B4.2.2.2.6', 'Represent and solve a given addition or subtraction problem involving a “part- part-whole” or comparison context, using a symbol to represent the unknown', 'E.g.; 1. Ask students to represent and solve these problems: (i) Eunice is Anita’s older sister. The difference between their ages is 21 years. Anita is 37 How old is Eunice? (ii) Ms. Akoto allowed 7 students to go to the washroom. There were 15 students left in the room. How many students are in the class?', 490),
('Basic 4', 'Mathematics', 'maths', 'Algebra', 'Unknowns, Expressions and Equations', 'B4.2.2.2', 'Solve one-step equations involving a symbol to represent an unknown number', 'B4.2.2.2.7', 'Create a problem for a given equation with one unknown', 'E.g.; 1. Provide an equation such as 14 +  = 21 or 25 -  =; 18. Ask students to create a matching story problem and solve it. Observe to what extent students are able to: -create a story to match the equation; - explain the meaning of the unknown variable; and - solve the problem in one or more way', 500),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'D and 3D Shapes', 'B4.3.1.1', 'Identify the lines of symmetry of regular and irregular 2D shapes', 'B4.3.1.1.1', 'Complete drawings of shapes to make them symmetrical', 'E.g.; 1. Give learners graph sheets to copy the incomplete 2D shape and it complete to make a symmetrical picture E.g.; 2. Give learners photocopied worksheets with several incomplete 2D shapes to complete with marked line of symmetry to complete the drawing.', 510),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'D and 3D Shapes', 'B4.3.1.1', 'Identify the lines of symmetry of regular and irregular 2D shapes', 'B4.3.1.1.2', 'Identify the lines of symmetry of regular and irregular 2D shapes (triangles and quadrilateral)', 'E.g.; 1. Give learners photocopied worksheets with symmetrical and non-symmetrical objects to sort and explain why they are symmetrical or not showing the lines of symmetry', 520),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Position / Transformation', 'B4.3.2.1', 'Describe the position of objects in space using the cardinal points', 'B4.3.2.1.1', 'Tell the position and motion of objects in space using the cardinal points north, south, east and west', 'E.g.; 1. Put pupils in convenient groups a give each group with a worksheet on graph with different labelled coordinates; some with axes labelled and other not etc. Pupils discuss their worksheets in their groups, then with whole class, describing coordinates, axes and pointing out errors on graphs if any E.g.; 2. Pupils describe the position and motion of objects: e.g. The point P is to the west of point T but to the north of the A E.g.; 3. Ask learners to locate the coordinates (i.e. ordered pairs of the location) of the Points; e.g. B is (2,-; 3) and T is (2,2)', 530),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.1', 'Describe the position of objects in space using the cardinal points', 'B4.3.3.1.1', 'Tell the position and motion of objects in space using the cardinal points north, south, east and west', 'E.g.; 1. Put pupils in convenient groups a give each group with a worksheet on graph with different labelled coordinates; some with axes labelled and other not etc. Pupils discuss their worksheets in their groups, then with whole class, describing coordinates, axes and pointing out errors on graphs if any E.g.; 2. Pupils describe the position and motion of objects: e.g. The point P is to the west of point T but to the north of the A E.g.; 3. Ask learners to locate the coordinates (i.e. ordered pairs of the location) of the Points; e.g. B is (2,-3) and T is (2,2)', 540),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.1', 'Describe the position of objects in space using the cardinal points', 'B4.3.3.1.2', 'Measure and record perimeter for regular and irregular shapes in cm and m', 'E.g. 1 Ask pupils to use a ruler to measure all the sides of a regular shape and sum up the result to obtain the perimeter P = 16cm E.g. 2 Pupils to explore the area of irregular cut-out shapes using graph sheets. Pupils to trace the shape on the graph sheet and count out the unit squares', 550),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.1', 'Describe the position of objects in space using the cardinal points', 'B4.3.3.1.3', 'Develop and apply a formula for determining perimeter of square and rectangle', 'E.g.; 1. Use cut out shapes to demonstrate how to determine the perimeter of 2-D shapes. Ask pupils to measure the sides of the cut out shape and add the results to obtain the perimeter E.g. 2 Given a rectangular cut out shape, ask pupils to measure the sides of the shape and determine the perimeter of the shape Therefore the perimeter of the triangle given is AB + AD + BC + CD. Thus 4cm + 2cm + 4cm + 2cm = 12cm', 560),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.1', 'Describe the position of objects in space using the cardinal points', 'B4.3.3.1.4', 'Construct different rectangles for a given perimeter (cm, m) to demonstrate that many shapes are possible for a perimeter', 'E.g.; 1. Given a perimeter of say 36cm, pupils to draw about three different rectangular shapes for the same perimeter. Combinations may include (6cm, 6cm, 12cm, 12cm; 8cm, 8cm, 10cm, 10cm; 4cm, 4cm, 14cm, 14cm, etc.)', 570),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.2', 'Demonstrate an understanding of area of regular and irregular 2-D shapes', 'B4.3.3.2.1', 'Recognise that area is measured in square units', 'E.g. 1 Pupils to explore the area of their exercise books. i.e. ask pupils to cut 1cm by 1cm square sheets and tack them on the back of their exercise books until it is covered entirely. Then, count the number of the sheets to obtain the area E.g.; 2. Pupils to explore the area of graph sheet. Ask pupils to calculate the area of one of the squares on the graph sheet. Then, count the number of squares on the graph sheet to obtain the area of the entire sheet E.g. 3 Using floor tiles, ask pupils to measure the area of one of the tiles, then multiply it by the number of tiles to obtain the area of the entire room Note: Help pupils to come out with the understanding that the area of a figure is the number of squares required to cover it completely', 580),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.2', 'Demonstrate an understanding of area of regular and irregular 2-D shapes', 'B4.3.3.2.2', 'Select and justify referents for the units cm2 or m2', 'E.g. 1 Let pupils explore the area of smaller objects say their exercise books. Then explore the area of larger objects say the entire classroom and compare the results for the two activities. Ask pupils to tell which unit (cm2 or m2) they will use for which activity and why?', 590),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.2', 'Demonstrate an understanding of area of regular and irregular 2-D shapes', 'B4.3.3.2.3', 'Estimate area by using referents for cm2 or m2', 'E.g. 1 Let pupils estimate the area of items in the classroom. Then measure the actual area and compare with their estimates E.g. 2 Pupils to measure the area of say their exercise books. With that as a reference point, ask them to estimate the area of the teacher’s table', 600),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.2', 'Demonstrate an understanding of area of regular and irregular 2-D shapes', 'B4.3.3.2.4', 'Develop and apply a formula for determining area of a rectangle and square', 'E.g. 1 Give pupils a standard graph sheet with 1 cm squares and ask them to draw a square of given length on the graph sheet. The area can be measured by counting the number of square units. So, we can count the number of unit units to find the area. In the diagram the area is 16cm2 since there are 36 squares in the shape E.g. 2 Ask pupils to count the number of cubic squares on the vertical section of the shape and multiply it by the number on the horizontal section Ask pupils to compare their answer with the first strategy and draw their own conclusions. The area of a square can be given as L × L and that of a rectangle is L × B.', 610),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.2', 'Demonstrate an understanding of area of regular and irregular 2-D shapes', 'B4.3.3.2.5', 'Construct different rectangles for a given area (cm2 or m2) in order to demonstrate that many different rectangles may have the same area', 'E.g.; 1. Given an area of say 24cm2, pupils should draw about three different rectangles for the same area. Combinations may include (6cm × 4cm; 8cm × 3cm; 12cm × 2cm, etc.)', 620),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.3', 'Demonstrate understanding of time taken by events in minutes and hours', 'B4.3.3.3.1', 'Tell the time in hours and minutes in analogue and digital watches including 24-hour clocks E.g .1 Use analogue clocks to tell time by keeping the hour hand on 12 and making jumps of 15(quarter past), 30(half past), 45(quarter to), and 60 (12 o’clock)', 'E.g. 2 Use analogue clocks to tell time by keeping the hour hand on any number say 3 and move the minutes hand to various numbers for different time (3:12, 3:25, 3:38, 3:50, etc. E.g. 3 Use analogue clocks to tell time by keeping the minutes hand on 12 and moving the hour hand to tell time at the hour mark E.g .4 Pupils should draw/sketch the face of the clock to tell time given', 630),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.3', 'Demonstrate understanding of time taken by events in minutes and hours', 'B4.3.3.3.2', 'Use clock to measure time to complete simple events in minutes and seconds', 'E.g. 1 Use the analogue clock to record the time it takes to say walk from the classroom to the canteen/head teacher’s office/library, etc. and back. (mostly minutes) E.g. 2 Use the digital watch to record say the time it takes to walk from the teacher’s table to the cupboard. (mostly seconds) E.g. 3 Ask pupils to tell the time it takes to complete activities like bathing, brushing teeth, ironing a shirt, cooking rice, etc.', 640),
('Basic 4', 'Mathematics', 'maths', 'Geometry and Measurement', 'Measurement- (Perimeter and Area)', 'B4.3.3.3', 'Demonstrate understanding of time taken by events in minutes and hours', 'B4.3.3.3.3', 'State dates of events and record calendar dates in a variety of formats', 'E.g.; 1. Record dates in different formats i. Tuesday, 28th August 2018 ii. 28th August, 2018 iii. 28-Aug-18 iv. 28/08/2018 v. 28.08.18 E.g.; 2. Ask pupils to write the dates for the following events from a calendar; i. Independence Day of Ghana ii. Republic Day iii. Founders’ Day iv. Farmers’ Day v. Workers’ Day', 650),
('Basic 4', 'Mathematics', 'maths', 'Data', 'Data Collection, Organization, Presentation, Interpretation and Analysis', 'B4.4.1.1', 'Demonstrate an understanding of many-to-one correspondence in displaying, and reading or interpreting, graphs', 'B4.4.1.1.1', 'Use an understanding of one-to-one correspondence to read and interpret graphs', 'E.g.; 1. Give learners graphs that use one-to-one correspondence in displaying data. For example, the graph below shows the favourite fruits of children in a P4 class. Each coloured box in the graph represents a pupil Ask the following questions for children to read and interpret graphs i. How many pupils said they like pawpaw? ii. What is the most favourite food of the class? How many pupils are in the class? Etc.', 660),
('Basic 4', 'Mathematics', 'maths', 'Data', 'Data Collection, Organization, Presentation, Interpretation and Analysis', 'B4.4.1.1', 'Demonstrate an understanding of many-to-one correspondence in displaying, and reading or interpreting, graphs', 'B4.4.1.1.2', 'Use an understanding of many-to-one correspondence to display or construct graphs', 'E.g.; 1. Display a table for of illnesses P4 pupils have had in school last academic year. Discuss with pupils how many objects/cut-outs will be required to display or construct a graph of the illnesses in the table ifrepresents 2 pupils Number of pupils visiting hospital Number of objects Illness with illnesses in graph Diarrhoea 10 5 Fever 16 8 Toothache 4 2 Headache 6 ∙ Stomach-ache 8 ∙ Cold 14 ∙ E.g.; 2. Put a chart with labelled axes on the board; places several card cut-outs of the object “”on the table. Ask pupils to go in turns to construct the graph of the illnesses in the chart by pasting the right number of cut-outs in the columns above each illness as in the figure below; Number of pupils visiting hospital with illnesses; 10; 16; 4; 6; 8; 14', 670),
('Basic 4', 'Mathematics', 'maths', 'Data', 'Data Collection, Organization, Presentation, Interpretation and Analysis', 'B4.4.1.1', 'Demonstrate an understanding of many-to-one correspondence in displaying, and reading or interpreting, graphs', 'B4.4.1.1.3', 'Compare graphs in which the same data has been displayed and explain how they are the same and different', 'E.g.; 1. Give learners several graphs that have used one-to-one correspondence in displaying the same data. For instance, the graph below shows the animals at Mr. Wilmot’s farm. Ask children to explain how they are the same and different', 680),
('Basic 4', 'Mathematics', 'maths', 'Data', 'Data Collection, Organization, Presentation, Interpretation and Analysis', 'B4.4.1.1', 'Demonstrate an understanding of many-to-one correspondence in displaying, and reading or interpreting, graphs', 'B4.4.1.1.4', 'Find examples of graphs in which many-to-one correspondence is used in print and electronic media, such as newspapers, magazines and the Internet, and describe the correspondence used', 'E.g.; 2. Give students data presented in a table to draw bar graph complete with title, labelled axes, key. The table show amount of rainfall recorded in Kumasi in the half of the year. January February March April May June 5mm 10mm 10mm 25mm 40mm 45mm Rainfall in mm E.g.; 3. Give pupils data on energy usage by households in a community over a period (e.g. six months) presented in tables for them to draw bar graph complete with title, labelled axes, key. Ask questions for pupils to read and interpret graphs.', 690),
('Basic 4', 'Mathematics', 'maths', 'Data', 'Data Collection, Organization, Presentation, Interpretation and Analysis', 'B4.4.1.2', 'Construct and interpret pictographs and bar graphs involving many-to-one correspondence to draw conclusions', 'B4.4.1.2.1', 'Identify common features of graphs that use many-to-one correspondence and use that understanding to draw bar graphs or pictographs, complete with title, labelled axes, key or legend, to represent data collected (up to 4 categories of data)', 'E.g.; 1. Refer to example in', 700),
('Basic 4', 'Mathematics', 'maths', 'Data', 'Data Collection, Organization, Presentation, Interpretation and Analysis', 'B4.4.1.2', 'Construct and interpret pictographs and bar graphs involving many-to-one correspondence to draw conclusions', 'B4.4.1.2.2', 'Use understanding of many-to-one correspondence to solve simple problems (how many altogether, comparing, or take apart problems) requiring interpretation of many-to- one bar graphs (up to 4 categories of data)', 'E.g.; 1. Give learners several graphs that have used many-to-one correspondence in displaying the same data. For example, the graph below on the number of pupils treated for malaria in a school. Ask questions for children to read and interpret graphs. i) How many pupils were treated for malaria in the hospital in April? ii) How many pupils were treated for malaria in the hospital in May and June? iii) How many pupils were treated for malaria in the hospital in the last three months of the year? iv) In which month was the largest number of people treated for malaria in the hospital?', 710),
('Basic 4', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B4.1.1.1', 'Explore the nature of God as the Creator B4 1.1.2. Appreciate the uniqueness of humankind and other creatures', 'B4.1.1.1.1', 'Explain the nature of God as the Creator', 'Lead learners to discuss the nature of God as the Creator: originator of all things, He created all things such as human beings, trees, animals, water bodies, etc.; Take learners on nature walk to observe and document things created by God: human beings, trees, animals, water bodies, etc.; In groups, learners put their findings together and present them to the class for discussion.', 10),
('Basic 4', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'God the Creator', 'B4.1.1.2', 'Explore the nature of God as the Creator B4 1.1.2. Appreciate the uniqueness of humankind and other creatures', 'B4.1.1.2.1', 'Identify the uniqueness of humankind from other creatures', 'Have learners in groups identify how different humankind is from other creatures of God: - human beings versus animals - human beings versus plants; Let learners, in groups, write down the characteristics of humankind: our thinking ability, ability to speak, knowing what is good and evil, etc.; Let each group present its list for peer-review and class discussion.; Let learners draw an animal and a human being and draw the comparison between the two.; Let learners write down the characteristics of humankind that are different from animals.', 20),
('Basic 4', 'Religious & Moral Education', 'rme', 'God, His Creation and Attributes', 'The Environment', 'B4.1.2.1', 'Explain the effects of human activities on the environment', 'B4.1.2.1.1', 'Discuss the effects of human activities on the environment', 'Guide learners to talk about the human activities in the environment.; Show pictures and video clips on human activities that destroy the environment: illegal mining (galamsey), indiscriminate cutting down of trees (deforestation), pollution of water bodies, air pollution, etc.; Let learners write the effects of human activities on the environment: climate change – heat, floods, rain storms, less rainfall, famine, drought, etc.', 30),
('Basic 4', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Religious Worship, Prayer and other Religious Practices', 'B4.2.1.1', 'Appreciate the importance of prayer, worship and other acts of worship', 'B4.2.1.1.1', 'Name the various forms of worship', 'Ask learners to mention the various forms of worship in the three main religious groups in Ghana: Christianity, Islam and Traditional.; Let learners observe pictures depicting various forms of worship and discuss them.; In groups, let learners write down the activities that go on during worship.; Let learners dramatise the modes of worship among the three major religious groups.', 40),
('Basic 4', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Religious Worship, Prayer and other Religious Practices', 'B4.2.1.1', 'Appreciate the importance of prayer, worship and other acts of worship', 'B4.2.1.1.2', 'State the purpose of worship in the three main religions', 'Together with learners, discuss why we worship God: to draw closer to God, to communicate with God, to show obedience to God, etc.; In groups, learners should recognise the need to take active part in worship.; Let learners draw and colour a worship scene.', 50),
('Basic 4', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Religious Worship, Prayer and other Religious Practices', 'B4.2.1.1', 'Appreciate the importance of prayer, worship and other acts of worship', 'B4.2.1.1.3', 'Differentiate between religious and non-religious songs', 'Ask learners to mention songs sung in Ghana.; Let learners differentiate between religious and non-religious songs by comparing the lyrics: religious songs express faith in God while non-religious songs portray worldly ideas, etc.; Let groups list titles of religious and non-religious songs.; Let learners sing some religious and non-religious songs.', 60),
('Basic 4', 'Religious & Moral Education', 'rme', 'Religious Practices and their Moral Implications', 'Festivals in the Three Major Religions', 'B4.2.2.1', 'Explore the significance of religious festivals', 'B4.2.2.1.1', 'Discuss festivals in their neighbourhood', 'Let learners mention festivals that are celebrated in their communities: Christmas, Easter, Eid-Ul-Fitr, Eid-Ul-Adha, Odwira, Aboakyir, etc.; Use pictures, charts or video clips to demonstrate how the various religious festivals are celebrated.; Let learners recite texts and sing songs that accompany festivals celebrated in their communities.; Put learners in groups to write activities that take place during festivals.; In their same groups or in pairs, let learners discuss the specific activities that take place during festivals, bringing out the following values: - Moral, - Social and - Economic.; Let groups present their findings for class discussions.', 70),
('Basic 4', 'Religious & Moral Education', 'rme', 'Religious Leaders', 'The Call of the Leaders of the Three Major Religions', 'B4.3.3.1', 'Explain the significance of the call of the main religious leaders', 'B4.3.3.1.1', 'Describe the call of the religious leaders', 'Have learners discuss the leaders of the three major religions in Ghana: - The Lord Jesus Christ as the son of God-His Baptism - The Holy Prophet Muhammad (S.A.W) - His encounter with Angel Jibril (Gabriel) in the Cave- Hijrah - The call of Traditional Religious Leader- OkomfoAnokye, TogbuiTsali, etc.; Invite a resource person to talk about the call of each religious personality.; Guide learners to discuss what they have heard about the religious personalities.; In groups, ask learners to dramatise or role-play the call of the religious personalities.; Let learners write on the call of the religious personalities and present their works to class for discussion.', 80),
('Basic 4', 'Religious & Moral Education', 'rme', 'The Family and Community', 'Roles and Relationships', 'B4.4.1.1', 'Exhibit the need to be committed to God', 'B4.4.1.1.1', 'Explain the need to be committed to God', 'Let learners mention the ways by which we are committed to God: - Prayer, - service to humankind, - caring for the environment, - helping the needy (charity), etc.; Guide learners to discuss the need to be committed to God: - God created us; It is a command from Him, - He provides our needs, - we get good things from Him, - we worship Him, etc.; In groups or in pairs, let learners mention the benefits of being committed to God: - blessings from God, - drawing closer to God, - health, - long life, - prosperity, - eternal life, etc.; In groups, let learners discuss why they have to be committed to God.; Let learners in pairs, write the benefits of responding to God’s call and present their works for class discussion.', 90),
('Basic 4', 'Religious & Moral Education', 'rme', 'The Family and Community', 'Roles and Relationships', 'B4.4.1.1', 'Exhibit the need to be committed to God', 'B4.4.1.1.2', 'Identify deeds that attract rewards', 'Lead learners to discuss deeds, attitudes and actions towards others and things in the environment.; Ask learners to write down good deeds: - helping one another - obedience to the constitution of Ghana, parents, teachers, school authorities, elders and rulers, etc.; Guide learners to know that refusal to do good deeds attracts punishment.; Put learners in groups to write down actions that are rewarded and those that are punished and present to class for discussion.; Let learners select texts from the sacred scriptures that talk about good deeds and dramatise them: - The Good Samaritan (Luke-10:25-37), - The Feeding of the Five Thousand-a little boy offered his loaf of bread (Mathew 14:16-21), - Righteous Deeds (Surah Hud, The Holy Quran 11:11) and - Traditional folktales and proverbs.', 100),
('Basic 4', 'Religious & Moral Education', 'rme', 'The Family and Community', 'Roles and Relationships', 'B4.4.1.1', 'Exhibit the need to be committed to God', 'B4.4.1.1.3', 'Give reasons for rewarding good deeds', 'Lead learners to re-call good deeds.; Let learners mention types of rewards: handshakes, hugs, praises, certificates, prizes, gifts, etc.; Guide learners to discuss the importance of good deeds: -to ensure law and order in society -to help everyone to develop good moral life -to encourage hardworking, etc.; Let learners, in pairs or groups, write essays on good deeds: - Why I will always do good - The rewards of being good Every good turn deserves another', 110),
('Basic 4', 'Religious & Moral Education', 'rme', 'The Family, Au thority and Obedience', 'Authority and Obedience', 'B4.5.1.1', 'Explain the need to obey and submit to authority', 'B4.5.1.1.1', 'Explain authority at home, school and in the community', 'Through questions and answers, let learners explain authority.; With the aid of picture cards, videos, wall charts, etc., let learners identify people in authority in their immediate community. NB Where possible, films can be used to guide the learners to identify the people in authority in the immediate communities.; Guide learners to identify those in authority at home, school and in their community: parents, head teachers, teachers, class prefect, sectional leaders, chiefs, pastors, Imams, etc.; Let learners dramatise or role-play authority at home, school and in the community.', 120),
('Basic 4', 'Religious & Moral Education', 'rme', 'The Family, Au thority and Obedience', 'Roles, Relationships in the Family and Character Formation', 'B4.5.2.1', 'Explain the importance of being a loyal member of the family', 'B4.5.2.1.1', 'Discuss the importance of being a committed member of the family', 'Assist learners to explain who a committed person is.; Let learners mention behaviours that show that a person is committed.; Ask learners to describe a committed family member. A person who: - takes part in family activities, - is obedient to elders of the family, - respects other family members, - accepts responsibility (performing assigned duties), - takes initiatives, - helps needy relatives, etc.; Help learners to discuss the importance of being a committed family member: - to promote unity, - to gain respect, - to be considered a trustworthy person, etc.; Let learners role-play or mime roles committed family members.', 130),
('Basic 4', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B4.1.1.1', 'Understand the physical features and life processes of living things and use this understanding to classify them', 'B4.1.1.1.1', 'Classify animals into insects, birds, mammals and reptiles', 'Learners embark on a walk to observe and record names of different kinds of animals in their community or show videos and pictures of different kinds of animals.; Learners talk about the different animals based on their limbs, body covering, height, shape, size, where they live, how they move, what they eat. etc.; Provide flashcards of many different animals to learners in groups.; Assist learners to sort the pictures into insects, birds, mammals and reptiles and produce animal classification cards or tables.; Learners display and do presentations on their group work.; Learners to give reasons for their classifications.; Ask Learners to identify things which are common to all the different kinds of animals.; Assist learners to mould different kinds of animals using suitable materials (such as blu tack, clay, cardboard etc.).; Learners draw different kinds of animals (insects, birds, mammals and reptiles).', 10),
('Basic 4', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B4.1.1.1', 'Understand the physical features and life processes of living things and use this understanding to classify them', 'B4.1.1.1.2', 'Know life processes of animals (movement, nutrition and reproduction)', 'Learners observe videos and pictures depicting movement, nutrition and reproduction in animals.; Learners describe how various animals (insects, birds, reptiles and mammals) move, feed and reproduce.; Learners role-play or pantomime movement and nutrition of animals.; In groups, learners discuss the importance of movement, nutrition and reproduction to animals. NB: Teachers should collect and preserve some common animals for presentation.', 20),
('Basic 4', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B4.1.1.2', 'Understand the differences between living things and things which have never been alive', 'B4.1.1.2.2', 'Describe the physical appearance of different types of plants (trees, shrubs, climbing, creeping)', 'Take learners out to observe different types of plants. Pictures and videos can also be used.; Learners describe the physical features of different types of plants (in terms of their structure and size). Project: Learners create a plant album of different types of plants. (shrubs, trees, climbing and creeping plants).', 30),
('Basic 4', 'Science', 'science', 'Diversity of Matter', 'Living and Non-living Things', 'B4.1.1.2', 'Understand the differences between living things and things which have never been alive', 'B4.1.1.2.3', 'Describe the physical features of mammals, reptiles, insects and amphibians', 'Learners observe mammals, reptiles, insects and amphibians through videos and pictures (or relevant specimen such as frogs, lizards, cockroaches).; Learners are guided to use think pair-share to identify and discuss the animals they have observed.; Learners describe the physical features of the animals stated in terms of their limbs, body covering, height, shape, size, where they live, how they move and what they eat.; Learners, in a matching activity, use flashcards to match specific animals with their identified physical features.', 40),
('Basic 4', 'Science', 'science', 'Diversity of Matter', 'Materials', 'B4.1.2.2', 'Understand mixtures, their types, formation, uses and ways of separating them into their components', 'B4.1.2.2.1', 'Identify a liquid-liquid mixture and describe how to separate its components', 'Display different types of liquids for learners to observe, e. g. water, kerosene, cooking oil, milk, soft drinks, etc.; Task learners to identify the liquids provided.; In groups, learners mix liquids of the same kind, different kinds and then observe and record their findings, e.g., vinegar and water, palm oil and water, etc.; Engage learners in discussion to describe the different types of liquid-liquid mixtures. [Those which are able to mix uniformly (miscible liquids) and those which are not able to mix uniformly (immiscible)]. Project: Separation of a mixture of immiscible liquids. Learners investigate to separate a mixture of immiscible liquids such as cooking oil and water. NB: This activity can be undertaken with the aid of a separating funnel or an improvised version of it. Do not bring liquids that are flammable or poisonous to class for this lesson.', 50),
('Basic 4', 'Science', 'science', 'Cycles', 'Earth Science', 'B4.2.1.1', 'Recognise that some events in our environment occur recurrently', 'B4.2.1.1.1', 'Demonstrate understanding of cyclic movements in the environment', 'Guide learners to build a pendulum (a ball hanging on a string) and let them observe the swinging motion.; Learners observe the following movements: (1) the second hands on an analogue clock (2) merry-go-round (3) a swinging pendulum, (4) movement of their limbs during walking.; Assist learners to come out with one thing that is common to all the movements. Project: Life Cycle of a Maize Plant Learners investigate the life cycle of a maize plant and report on their findings.', 60),
('Basic 4', 'Science', 'science', 'Cycles', 'Earth Science', 'B4.2.1.2', 'Recognise the relationship between the earth and the sun', 'B4.2.1.2.1', 'Identify the objects in the sky during day and night', 'Ask learners to step outside the classroom and: (a) name the objects in the daytime sky; (b) identify the objects in the night time sky; (c) identify the differences and similarities in day and night sky, (d). answer the question: what happens to the sky in a 24-hour cycle?; Learners draw Venn diagrams (2 circles then another circle overlapping the two) and put in them the things they see in the night sky, day sky and then in both skies and display their work on the classroom walls.; Learners write about the importance of the things they see in the skies.', 70),
('Basic 4', 'Science', 'science', 'Cycles', 'Earth Science', 'B4.2.1.3', 'Show understanding of the roles of condensation, evaporation, transpiration and precipitation in the hydrological (water) cycle', 'B4.2.1.3.1', 'Demonstrate the process of evapotranspiration', 'Guide learners are guided to breathe out or blow air onto a transparent surface, e.g. a glass or plastic bottle and share their observations.; Explain to learners that just as humans release water vapour when they respire, so do plants when they transpire.; Put learners into groups and give each group a young potted plant, plastic wrap bag and a rubber band to undertake the following activities: (1) Let learners examine the surface of the leaves of the plants and mop off any water droplets on the leaves. (2) Tie the plastic wrap bag around the plant up to the stem and leave it for an hour. (3) Observe both plant and plastic wrap surfaces. (4) Let learners report on what happens.', 80),
('Basic 4', 'Science', 'science', 'Cycles', 'Earth Science', 'B4.2.1.5', 'Recognise water and air as important natural resources', 'B4.2.1.5.1', 'Demonstrate ways of making water safe for use', 'Learners identify the sources of water in the community.; Learners discuss qualities of good drinking water.; Provide learners with samples of water from the following sources: rivers, wells, lagoons, boreholes, ponds and standpipe, etc.; Learners brainstorm on how to make water safe for use.; Learners, in groups, demonstrate the different ways of making water safe. For example, filtering, boiling, addition of iodine tablets, use of chlorine, use of water filters, addition of alum, etc.; Learners discuss the dangers of drinking unsafe water. Note: Teacher to supply materials for this activity. Precaution: Learners must not taste any of the water samples used in the lesson.', 90),
('Basic 4', 'Science', 'science', 'Cycles', 'Life Cycles of Organisms', 'B4.2.2.1', 'Demonstrate understanding of the life cycle of plants', 'B4.2.2.1.1', 'Observe, identify and give functions of the parts of a plant', 'Learners, in groups, uproot young plants from the school surroundings for a class activity.; Learners observe, identify and give functions of parts of the plants (roots, stem, leaves and flower).; Learners draw annotated diagrams of the plants and display them in class.; Learners relate the functions of the parts to their positions on the plant.', 100),
('Basic 4', 'Science', 'science', 'Cycles', 'Life Cycles of Organisms', 'B4.2.2.1', 'Demonstrate understanding of the life cycle of plants', 'B4.2.2.1.2', 'Examine some common seeds and how they germinate', 'Review learner’s knowledge that seeds can germinate with or without soil.; This activity will take some days. NB: It is a repeat of the B3 activity but this time, the focus is on the process of germination.; Learners will work with beans or maize seeds. Learners first observe the dry seed coat, then when it absorbs water to swell rapturing of seed coat, sprouting of the root, sprouting of the stem and seed leaves, the elongation of the root and stem.; Learners follow the process and write reports. NB: Report should include diagrams of each stage of germination.', 110),
('Basic 4', 'Science', 'science', 'Systems', 'The Human Body Systems', 'B4.3.1.1', 'Recognise that different parts of the human body work interdependently to perform a specific function', 'B4.3.1.1.1', 'Know the organs of the digestive system and their functions', 'Show videos, pictures and models of the digestive system.; Learners keenly observe the organs of the digestive system.; Explain to learners the functions of the various organs in the digestive system.; Draw a diagram of the digestive system and cut out the various parts of the system into flash cards.; Learners randomly pick the parts of the digestive system on flashcards.; Learners build the digestive system by arranging the parts in an orderly manner as they appear in the digestive system.; Engage learners in an activity to role-play the various parts of the digestive system and their functions, with the aid of flashcards.', 120),
('Basic 4', 'Science', 'science', 'Systems', 'The Solar System', 'B4.3.2.1', 'Show an understanding of the orderliness of the sun, planets and satellites in the solar system, as well as the important role of the sun in the existence of the solar system', 'B4.3.2.1.1', 'Explain that the sun is at the centre of the solar system', 'Present learners with a chart, model or video showing the solar system.; Draw the solar system, using different colours to illustrate the different bodies.; Guide learners to role-play the stars, planets and satellites in the solar system (different learners assume and role-play the sun, the earth and other planets in the solar system).; Present the chart of the solar system and help learners identify the sun as being at the centre of the solar system.; Learners are guided to identify the benefits of the sun to the solar system. Project: Learners mould stars, planets and satellites in the solar system.', 130),
('Basic 4', 'Science', 'science', 'Systems', 'Ecosystem', 'B4.3.3.1', 'Show understanding and appreciation of the interactions and interdependencies of organisms in an ecosystem', 'B4.3.3.1.1', 'Explain the concept of ecosystem', 'Learners role-play a typical family setup, showing how everyone is interdependent.; Learners identify the role of each member of their family, e.g. father, mother, siblings. The key lesson is to understand that everybody in the group is important and depend on one another.; Teacher mentions a habitat and the learners mention which plants, animals, and other organisms live there (Use games).; Show pictures and videos of forest settings having trees, grass, a stream, soil, fishes, rodents, frogs, etc. to explain to learners what an ecosystem looks like.; Learners discuss the importance of every element/member of a given ecosystem, e.g. frogs, weeds, soil and fish in a pond.; Brainstorm with learners to come out with responses to what happens when a member of the system is removed.; Assist learners to realise that it causes imbalance in the ecosystem. Relate the concept to everyday life, e.g. the destruction of the forest through galamsey and the felling of trees bring about imbalances in the environment.; Learners cite examples of ecosystems in their community and suggest ways of preserving them.', 140),
('Basic 4', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B4.4.1.1', 'Demonstrate understanding of the concept of energy, its various forms, sources and how to transform and conserve it', 'B4.4.1.1.1', 'Identify the effect of heat on the change of state of substances', 'Guide learners through simple activities to identify effects of heat on substances (use liquids and solids, e.g. water, shea butter, candles, etc.).; Learners demonstrate evaporation by boiling water and discuss their experiences. Note: let learners measure the quantity of the water before and after boiling to show the effect of heat on water.; Elaborate on learners’ ideas to explain how the escaping vapour can be changed into water (through the loss of heat).', 150),
('Basic 4', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B4.4.2.1', 'Demonstrate knowledge of generation of electricity, its transmission and transformation into other forms', 'B4.4.2.1.1', 'Identify the uses of electricity', 'Begin by asking learners what they use to iron their school uniforms.; Use simple activities to demonstrate uses of electricity, (e.g. providing light, powering TVs, mobile phones, cooking, heating water, etc.); Learners draw things in the home and at school that use electricity. Project: Electricity Generation Learners, in groups, generate electricity from fruit cells (orange, lime, tomatoes, potatoes and apple) and fuel cells, e.g. water.', 160),
('Basic 4', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B4.4.2.1', 'Demonstrate knowledge of generation of electricity, its transmission and transformation into other forms', 'B4.4.2.1.2', 'Describe ways of conserving electricity', 'Learners explain why their parents put off the lights, television and other electrical appliances when leaving the house in the morning.; Discuss with learners what happens when electrical gadgets such as heaters and pressing irons are left on when leaving the house.; Learners work in groups to discuss activities that contribute to wastage of electricity.; Based on their responses, facilitate a discussion on ways of conserving electricity.; Learners present their ideas to class for discussion. Project: Monitoring electricity consumption in the home and at school. Learners record the amount of electricity consumed in their homes or at school over a period of three (3) months and report on their findings.', 170),
('Basic 4', 'Science', 'science', 'Forces and Energy', 'Sources and Forms of Energy', 'B4.4.2.2', 'Know the functions and assemblage of basic electronics components', 'B4.4.2.2.1', 'Identify the basic components of electronic circuits', 'Learners are put into groups and each group is provided with connecting wires, batteries (dry cells), switches and LEDs (of different colours).; Learners are assisted to identify the various components provided.; Learners observe a demonstration on how to connect the components to light the LED.; Learners are guided to connect the components to make the LED produce light.; Engage learners to discuss the use of each component; Learners draw the circuits they have connected.; Learners suggest other materials that can be used in the absence of the connecting wire.; Learners act as electrons flowing in a circuit through the classroom. Learners act out the role of various components (resistor, capacitor, etc) in the circuit. NB: Build a stock of electronic components from discarded electronic gadgets such as radio and TV sets.', 180),
('Basic 4', 'Science', 'science', 'Forces and Energy', 'Forces and Movement', 'B4.4.3.1', 'Know that movement is caused by applied forces due to the release of stored energy', 'B4.4.3.1.1', 'Demonstrate understanding of elastic and compressional forces and their everyday applications', 'Learners bring catapults, rubber bands, springs and bicycle pumps to class.; Guide learners to demonstrate different effects of forces, e.g. by kicking a ball in different directions, pushing a table, crumpling a piece of paper or stopping a moving toy.; Engage learners in activities to demonstrate elastic and compression forces using the materials brought to class.; Learners to discuss how elastic and compressional forces are applied in everyday life.', 190),
('Basic 4', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B4.5.1.1', 'Recognise the importance of personal hygiene', 'B4.5.1.1.1', 'Know how to care for one’s self and the environment', 'Learners brainstorm in groups and share ideas with the whole class on what they do to maintain personal hygiene.; Learners write their ideas on flashcards (ideas may include bathing twice daily, cleaning the teeth, cutting their finger nails, washing their towels, sweeping their classrooms, etc.).; Brainstorm with learners on what will happen if they do not take good care of their bodies.; Learners are assigned to investigate materials that can be used to enhance personal hygiene (to brush the teeth, clean the armpit or bath).', 200),
('Basic 4', 'Science', 'science', 'Humans and the Environment', 'Personal Hygiene and Sanitation', 'B4.5.1.1', 'Recognise the importance of personal hygiene', 'B4.5.1.1.2', 'Describe ways of sustaining the environment through waste management', 'Learners watch pictures and videos on how to sustain the environment, including separating waste.; Engage learners in groups to mention the types of waste they produce in the home and at school, e.g. paper, rubber, bottles, etc.; Write learners’ ideas on the board and let them brainstorm on what will happen if the wastes they produce are not separated.; Evaluate learners by asking them to perform individual tasks, e.g. by writing down four practical ways of sustaining the environment. Project: Design Litterbins to hold different forms of waste. Learners make or mould litterbins and other equipment from suitable materials for holding different types of waste.', 210),
('Basic 4', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B4.5.2.1', 'Know common diseases of humans; causes, symptoms, effects and prevention', 'B4.5.2.1.1', 'Identify causes, symptoms and prevention of measles', 'Learners watch pictures, videos or charts on causes, symptoms and prevention of measles or invite a health personnel or School Health Education Programme (SHEP) coordinator to give a talk on measles.; In pairs, learners answer the following questions based on the pictures and videos: (1) What causes measles? (2) What are the symptoms of measles? (3) What should be done if someone is exposed to measles? (4) What are the ways of preventing the spread of measles? Project: Learners develop concept maps to show the causes, symptoms and prevention of measles. Learners develop posters to talk about how they can prevent measles.', 220),
('Basic 4', 'Science', 'science', 'Humans and the Environment', 'Diseases', 'B4.5.2.1', 'Know common diseases of humans; causes, symptoms, effects and prevention', 'B4.5.2.1.2', 'Demonstrate understanding of the causes, symptoms and prevention of food-borne diseases', 'Learners watch pictures and videos on causes, symptoms and prevention of food borne diseases.; Invite a health personnel, SHEP coordinator or personnel from the Food and Drugs Authority (FDA) to give a talk on food-borne diseases.; In pairs, let learners respond to the following questions: (1). What causes food-borne diseases? (2). What are the symptoms of food-borne diseases? (3). What should be done if someone contracts a food-borne disease?; In pairs, learners give examples of food-borne diseases in their localities, i.e. cholera, diarrhoea, typhoid fever, etc.; Learners predict what will happen when someone contracts a food-borne disease.; Evaluate learners by asking them to prepare posters on the prevention and control of food-borne.', 230),
('Basic 4', 'Science', 'science', 'Humans and the Environment', 'Climate Change', 'B4.5.4.1', 'Know that climate change is one of the most important environmental issues facing the world today', 'B4.5.4.1.1', 'Explain that burning is one of the causes of climate change', 'Learners watch pictures and videos or charts showing burning of fossil fuel and changing weather pattern.; Narrate to learners a story of a bush fire and the effect it has on humans, plants, animals and property.; Learners, in groups discuss what happens when burning occurs.; Learners present their ideas, i.e. burning brings out smoke, makes air dirty or unclean, etc.; Brainstorm with learners on what will happen if there is continuous burning of vegetation and waste.; Evaluate learners by asking them to design posters on the effect of burning on climate change.', 240);
